export const findCardInState = (
  state: GameState,
  cardId: string,
): GameCard | undefined => {
  let foundCard: GameCard | undefined = undefined;
  for (const lane of state.lanes) {
    for (const slot of lane.slots) {
      if (slot?.id === cardId) {
        foundCard = slot;
        break;
      }
    }
  }

  if (foundCard) {
    return foundCard;
  }
  for (const p of state.players) {
    for (const c of p.hand) {
      if (c.id === cardId) {
        foundCard = c;
        break;
      }
    }
    if (foundCard) {
      return foundCard;
    }
    for (const c of p.discard) {
      if (c.id === cardId) {
        foundCard = c;
        break;
      }
    }
    if (foundCard) {
      return foundCard;
    }
  }

  return foundCard;
};
