import { useTurnManager } from './useTurnManager';
import { useInputHandler } from './useInputHandler';
import { api } from '../services/api';

export const useGameLogic = () => {
    // 1. Game State & Phases
    const { 
        gameState, 
        events, 
        isResolving, 
        isWaiting, 
        setIsWaiting, 
        startResolution, 
        restartGame: engineRestart, 
        resign: engineResign 
    } = useTurnManager();

    // 2. Input & UI State
    const {
        pendingMoves,
        setPendingMoves,
        selectedCardIdx,
        setSelectedCardIdx,
        showUndoMenu,
        setShowUndoMenu,
        isResultsHidden,
        setIsResultsHidden,
        inspectingCard,
        setInspectingCard,
        inspectingLocation,
        setInspectingLocation,
        currentEnergy,
        handleCardClick,
        handleLaneClick,
        handleUndoAll,
        resetInput
    } = useInputHandler(gameState);

    // --- High Level Orchestration ---

    const handleEndTurn = async () => {
        if (gameState.phase !== 'planning' || isResolving || isWaiting) return;

        // Lock UI
        setIsWaiting(true);
        setShowUndoMenu(false);
        setSelectedCardIdx(null);

        try {
            // Call the "Server"
            // We send our moves, and we get back the opponent's moves.
            // In a real deterministic simulation, we might also get back a 'seed' for RNG.
            const { opponentMoves } = await api.submitTurn(gameState, pendingMoves);

            // Proceed to Resolution (Client-side Replay/Simulation)
            startResolution(pendingMoves, opponentMoves);

            // Clear local pending moves (they are now committed in the engine state)
            setPendingMoves([]);
        } catch (e) {
            console.error("Failed to submit turn:", e);
            setIsWaiting(false);
        }
    };

    const restartGame = () => {
        engineRestart();
        resetInput();
    };

    const handleResign = () => {
        engineResign();
    };

    const onLocationClick = (laneIdx: number) => {
         if (isResolving || isWaiting || gameState.phase !== 'planning') return;

         const success = handleLaneClick(laneIdx);
         if (success) {
             // Could add a specific sound or feedback here via return value if needed
         }
    };

    return {
        gameState,
        events,
        pendingMoves,
        setPendingMoves,
        isResolving,
        isWaiting,
        selectedCardIdx,
        setSelectedCardIdx,
        showUndoMenu,
        setShowUndoMenu,
        inspectingCard,
        setInspectingCard,
        inspectingLocation,
        setInspectingLocation,
        isResultsHidden,
        setIsResultsHidden,
        currentEnergy,
        restartGame,
        handleResign,
        handleEndTurn,
        handleUndoAll,
        handleCardClick,
        handleLocationClick: onLocationClick
    };
};

