import { CARDS, LOCATION_DEFS, PLAYER_DECK_IDS, OPPONENT_DECK_IDS } from '../constants';
import { INITIAL_HAND_SIZE, MAX_TURNS, MAX_ENERGY } from '../config';
import { GameState, CardInstance, Lane, PlayerID, EffectContext, ActionSet, ExecutionTask, PlayerState } from '../types';
import { resolveEffect } from './effects';
import { applyContinuousEffects } from './statSystem';
import { cloneState, queueEvent, playCardFromHand, drawCard, addCardToHand, moveCard, addCardToLane, modifyPower, compactLane, discardCard } from './mutations';
import { calculateLanePower, findCardInState } from './selectors';
import { createCardInstance, createEmptyLane } from './factories';
import { PendingMove } from './planning';
import { queueTagTriggers, queueAbility } from './triggers';

// --- Initialization ---

export const createInitialGameState = (): GameState => {
  // 1. Setup Decks
  const p1Deck: CardInstance[] = PLAYER_DECK_IDS.map(id => {
    const def = CARDS.find(c => c.id === id)!;
    return createCardInstance(def, 'p1', 'DECK');
  }).sort(() => Math.random() - 0.5);

  const p2Deck: CardInstance[] = OPPONENT_DECK_IDS.map(id => {
    const def = CARDS.find(c => c.id === id)!;
    return createCardInstance(def, 'p2', 'DECK');
  }).sort(() => Math.random() - 0.5);

  // 2. Draw Initial Hands
  const p1Hand = p1Deck.splice(0, INITIAL_HAND_SIZE);
  const p2Hand = p2Deck.splice(0, INITIAL_HAND_SIZE);

  p1Hand.forEach(c => c.zone = 'HAND');
  p2Hand.forEach(c => c.zone = 'HAND');

  // 3. Setup Lanes
  const selectedLocs = [...LOCATION_DEFS].sort(() => Math.random() - 0.5).slice(0, 3);
  const lanes: [Lane, Lane, Lane] = [
      createEmptyLane(selectedLocs[0]), 
      createEmptyLane(selectedLocs[1]), 
      createEmptyLane(selectedLocs[2])
  ];

  // 4. Initial State Assembly
  const p1State: PlayerState = {
    energy: 1,
    stats: { destroyedCount: 0, destroyedPower: 0 },
    hand: p1Hand,
    deck: p1Deck,
    discardPile: [],
    destroyedPile: [],
    banishedPile: [],
  };
  const p2State: PlayerState = {
    energy: 1,
    stats: { destroyedCount: 0, destroyedPower: 0 },
    hand: p2Hand,
    deck: p2Deck,
    discardPile: [],
    destroyedPile: [],
    banishedPile: [],
  };

  let initialState: GameState = {
    turn: 1,
    maxTurns: MAX_TURNS,
    nextPlayOrder: 0,
    priority: 'p1', // Default
    players: {
      p1: p1State,
      p2: p2State,
    },
    lanes,
    winner: null,
    phase: 'planning',
    history: ['Game Started (Spec v1.4.0)'],
    eventQueue: [],
    executionQueue: [],
  };

  return applyContinuousEffects(initialState);
};

// --- Atomic Operations ---

export const executeDestroy = (state: GameState, instanceId: string): GameState => {
    let s = state;
    const lookup = findCardInState(s, instanceId);

    if (!lookup || lookup.location !== 'board') return s;

    const { card, laneIdx, slotIdx, owner } = lookup;

    // 1. Remove from Lane (Atomic)
    if (owner === 'p1') s.lanes[laneIdx!].p1Slots[slotIdx!] = null;
    else s.lanes[laneIdx!].p2Slots[slotIdx!] = null;

    // Close gap immediately
    compactLane(s.lanes[laneIdx!], owner);

    // 2. Update Card State
    card.zone = 'DESTROYED';
    card.laneIndex = null;
    card.slotIndex = null;

    // 3. Update Game Stats
    const playerState = s.players[owner];
    playerState.stats.destroyedCount++;
    playerState.stats.destroyedPower += card.totalPower;

    // 4. Visuals - Trigger both VFX and SFX for the "Pop" feel
    s = queueEvent(s, { type: 'VFX_PLAY', vfxId: 'vfx_explosion_small', laneIdx, slotIdx, playerId: owner });
    s = queueEvent(s, { type: 'SFX_PLAY', sfxId: 'sfx_destroy_digital' });

    // 5. Move to Pile
    playerState.destroyedPile.push(card);

    // 6. Queue OnDestroy Effects (Stack: LIFO)
    if (card.def.tags.includes('OnDestroy')) {
        s = queueAbility(s, card, 'OnDestroy');
    }

    s.history.push(`${card.def.name} was destroyed.`);
    return s;
};

// --- Execution Queue Processor (THE STACK) ---

/**
 * Executes EXACTLY ONE task from the stack.
 * Used by the UI loop to provide visual pacing (wait between steps).
 */
export const stepExecutionQueue = (state: GameState): GameState => {
    let s = cloneState(state);

    if (s.executionQueue.length === 0) return s;

    // POP from the end (Top of Stack)
    const task = s.executionQueue.pop()!;

    switch (task.type) {
        case 'TRIGGER_ABILITY': {
            const lookup = findCardInState(s, task.sourceId);

            if (lookup) {
                const { card, laneIdx, slotIdx, owner, location } = lookup;

                // ZONE INTEGRITY CHECK
                const isDestroyTrigger = task.triggerTag === 'OnDestroy';
                let isValid = false;
                if (isDestroyTrigger) {
                    isValid = location === 'board' || location === 'destroyed';
                } else {
                    isValid = location === 'board';
                }

                if (isValid) {
                    const ctx: EffectContext = {
                        player: owner,
                        laneIndex: laneIdx ?? 0, 
                        slotIndex: slotIdx ?? 0,
                        gameRegistry: CARDS,
                        actions: createActionSet() 
                    };

                    s = resolveEffect(card.def.effect, s, card, ctx);
                }
            }
            break;
        }

        case 'REVEAL_CARD': {
            const lookup = findCardInState(s, task.sourceId);

            // Only reveal if it's currently on the board
            if (lookup && lookup.location === 'board') {
                 const { card, laneIdx, slotIdx, owner } = lookup;

                 // Only reveal if currently hidden (idempotency)
                 if (!card.faceUp) {
                     card.faceUp = true;
                     s = applyContinuousEffects(s);

                     // Visuals
                     if (card.def.sfxOnReveal) {
                         s = queueEvent(s, { type: 'SFX_PLAY', sfxId: card.def.sfxOnReveal });
                     }
                     if (card.def.vfxOnReveal) {
                         s = queueEvent(s, { type: 'VFX_PLAY', vfxId: card.def.vfxOnReveal, laneIdx, slotIdx, playerId: owner });
                     }

                     // Trigger Ability
                     // This pushes the TRIGGER_ABILITY task to the stack, 
                     // so it executes immediately after this task finishes (LIFO).
                     if (card.def.tags.includes('OnReveal')) {
                         s = queueAbility(s, card, 'OnReveal');
                     }

                     s.history.push(`${card.def.name} was revealed (Summon).`);
                 }
            }
            break;
        }

        case 'EXECUTE_DISCARD': {
            const lookup = findCardInState(s, task.sourceId);
            if (lookup && lookup.location === 'hand') {
                    const { card, owner } = lookup;
                    const playerState = s.players[owner];

                    playerState.hand = playerState.hand.filter(c => c.instanceId !== task.sourceId);
                    playerState.discardPile.push(card);

                    card.zone = 'DISCARDED';
                    s = queueEvent(s, { type: 'SFX_PLAY', sfxId: 'sfx_ui_click' });
                    s.history.push(`${card.def.name} was discarded.`);
            }
            break;
        }

        case 'RUN_EFFECT': {
            const lookup = findCardInState(s, task.sourceId);
            if (lookup) {
                const { card, laneIdx, slotIdx, owner } = lookup;
                const ctx: EffectContext = {
                    player: owner,
                    laneIndex: laneIdx ?? 0, 
                    slotIndex: slotIdx ?? 0,
                    gameRegistry: CARDS,
                    actions: createActionSet(),
                    params: task.params
                };
                s = resolveEffect(task.effectId, s, card, ctx);
            }
            break;
        }
    }

    return applyContinuousEffects(s);
};

/**
 * Drains the entire queue synchronously. 
 * Use this for fast-forwarding or non-visual logic (like start of game).
 */
export const processExecutionQueue = (state: GameState): GameState => {
    let s = state;
    let ops = 0;
    const MAX_OPS = 100;

    while (s.executionQueue.length > 0 && ops < MAX_OPS) {
        s = stepExecutionQueue(s);
        ops++;
    }
    return s;
};

const createActionSet = (): ActionSet => ({
    destroyCard: (s, id) => executeDestroy(s, id),
    addCardToHand: (s, c) => addCardToHand(s, c),
    moveCard: (s, id, t) => moveCard(s, id, t),
    addCardToLane: (s, c, l) => addCardToLane(s, c, l),
    modifyPower: (s, id, d, src) => modifyPower(s, id, d, src),
    recalcState: (s) => applyContinuousEffects(s),
    playSfx: (s, sfxId) => queueEvent(s, { type: 'SFX_PLAY', sfxId })
});

// --- Phase Management ---

export const moveCardsToBoard = (state: GameState, p1Moves: PendingMove[], p2Moves: PendingMove[]): GameState => {
    let s = cloneState(state);
    p1Moves.forEach(move => { s = playCardFromHand(s, move.cardInstanceId, move.laneIdx); });
    p2Moves.forEach(move => { s = playCardFromHand(s, move.cardInstanceId, move.laneIdx); });
    return applyContinuousEffects(s);
};

export const getNextReveal = (state: GameState): { laneIdx: number, slotIdx: number, owner: PlayerID } | null => {
    const priorityPlayer = state.priority;
    const nonPriorityPlayer = state.priority === 'p1' ? 'p2' : 'p1';

    const unrevealedCards: CardInstance[] = [];

    // 1. Collect all unrevealed cards from the board
    for (const lane of state.lanes) {
        for (const card of [...lane.p1Slots, ...lane.p2Slots]) {
            if (card && !card.faceUp) {
                unrevealedCards.push(card);
            }
        }
    }

    if (unrevealedCards.length === 0) {
        return null;
    }

    // 2. Separate by player
    const priorityPlayerUnrevealed = unrevealedCards.filter(c => c.owner === priorityPlayer);
    const nonPriorityPlayerUnrevealed = unrevealedCards.filter(c => c.owner === nonPriorityPlayer);

    // 3. Sort each player's cards by playOrder (lower is earlier)
    priorityPlayerUnrevealed.sort((a, b) => (a.playOrder ?? Infinity) - (b.playOrder ?? Infinity));
    nonPriorityPlayerUnrevealed.sort((a, b) => (b.playOrder ?? Infinity) - (a.playOrder ?? Infinity));

    // 4. Determine the very next card to reveal
    const nextCardToReveal = priorityPlayerUnrevealed[0] ?? nonPriorityPlayerUnrevealed[0];

    if (nextCardToReveal) {
        return {
            laneIdx: nextCardToReveal.laneIndex!,
            slotIdx: nextCardToReveal.slotIndex!,
            owner: nextCardToReveal.owner
        };
    }

    return null;
};

// Updated: Only queues the reveal ability, does NOT drain queue automatically
export const revealCard = (state: GameState, laneIdx: number, slotIdx: number, owner: PlayerID): GameState => {
    let s = cloneState(state);
    const lane = s.lanes[laneIdx];
    const slot = owner === 'p1' ? lane.p1Slots[slotIdx] : lane.p2Slots[slotIdx];

    if (!slot) return s;

    slot.faceUp = true;
    s = applyContinuousEffects(s); 

    if (slot.def.tags.includes('OnReveal')) {
        s = queueAbility(s, slot, 'OnReveal');
    }

    if (slot.def.sfxOnReveal) {
        s = queueEvent(s, { type: 'SFX_PLAY', sfxId: slot.def.sfxOnReveal });
    }
    if (slot.def.vfxOnReveal) {
        s = queueEvent(s, { type: 'VFX_PLAY', vfxId: slot.def.vfxOnReveal, laneIdx, slotIdx, playerId: owner });
    }

    return s;
};

// Updated: Only queues, doesn't drain
export const resolveEndOfTurn = (state: GameState): GameState => {
    let s = cloneState(state);
    s = queueTagTriggers(s, 'EndOfTurn');
    return s;
};

// Updated: Only queues, doesn't drain
export const startNextTurn = (state: GameState): GameState => {
    let s = cloneState(state);

    s.turn++;
    s.players.p1.energy = Math.min(s.turn, MAX_ENERGY);
    s.players.p2.energy = Math.min(s.turn, MAX_ENERGY);

    s = drawCard(s, 'p1');
    s = drawCard(s, 'p2');

    const p1Power = s.lanes.reduce((acc, l) => acc + calculateLanePower(l, 'p1', s), 0);
    const p2Power = s.lanes.reduce((acc, l) => acc + calculateLanePower(l, 'p2', s), 0);

    if (p1Power > p2Power) s.priority = 'p1';
    else if (p2Power > p1Power) s.priority = 'p2';

    s = queueTagTriggers(s, 'StartOfTurn');

    s.phase = 'planning';
    return applyContinuousEffects(s);
};

export const calculateWinner = (state: GameState): PlayerID | 'draw' => {
    let p1Wins = 0;
    let p2Wins = 0;

    state.lanes.forEach(lane => {
        const p1 = calculateLanePower(lane, 'p1', state);
        const p2 = calculateLanePower(lane, 'p2', state);
        if (p1 > p2) p1Wins++;
        if (p2 > p1) p2Wins++;
    });

    if (p1Wins > p2Wins) return 'p1';
    if (p2Wins > p1Wins) return 'p2';

    const totalP1 = state.lanes.reduce((acc, l) => acc + calculateLanePower(l, 'p1', state), 0);
    const totalP2 = state.lanes.reduce((acc, l) => acc + calculateLanePower(l, 'p2', state), 0);

    if (totalP1 > totalP2) return 'p1';
    if (totalP2 > totalP1) return 'p2';

    return 'draw';
};

import { CardDefinition } from '../types';
import { getImg } from '../utils/assets';
import { OnRevealEffect } from '../types';
import { createCardInstance } from '../services/factories';
import { pickRandomCard } from '../services/queries';

export const PortalMage: CardDefinition = {
    id: 'c9',
    name: 'Portal Mage',
    rarity: 'Legendary',
    baseCost: 4,
    basePower: 4,
    tags: ['OnReveal', 'Summon'],
    baseText: 'On Reveal: Add two random 1-cost cards here.',
    effect: 'PortalMageEffect',
    imageUrl: getImg(9),
};

export const PortalMageEffect: OnRevealEffect = (state, source, context) => {
    let s = state;
    const newCardIds: string[] = [];

    // 1. Create and Add Cards (Face Down)
    for (let i = 0; i < 2; i++) {
        const def = pickRandomCard(context.gameRegistry, { cost: 1 });
        if (def) {
            // Create instance (Default creation is faceUp=false for BOARD, but being explicit is good)
            const newCard = createCardInstance(def, source.owner, 'BOARD');
            newCard.faceUp = false; 
            newCard.created = true;

            // Use DI Action to place in lane
            s = context.actions.addCardToLane(s, newCard, context.laneIndex);

            // Track ID
            newCardIds.push(newCard.instanceId);
        }
    }

    // 2. Queue Reveal Tasks
    // We want the cards to reveal sequentially.
    // The executionQueue is a LIFO stack. 
    // If we want [Card 1 Reveal] then [Card 2 Reveal], 
    // we must Push [Reveal Card 2] then Push [Reveal Card 1].
    // Pop -> Reveal Card 1. Pop -> Reveal Card 2.
    // So we iterate in reverse order of the `newCardIds` array.

    newCardIds.reverse().forEach(id => {
        s.executionQueue.push({
            type: 'REVEAL_CARD',
            sourceId: id
        });
    });

    return s;
};

import { CARDS, LOCATION_DEFS, PLAYER_DECK_IDS, OPPONENT_DECK_IDS } from '../constants';
import { INITIAL_HAND_SIZE, MAX_TURNS, MAX_ENERGY } from '../config';
import { GameState, CardInstance, Lane, PlayerID, EffectContext, ActionSet, ExecutionTask, PlayerState } from '../types';
import { resolveEffect } from './effects';
import { applyContinuousEffects } from './statSystem';
import { cloneState, queueEvent, playCardFromHand, drawCard, addCardToHand, moveCard, addCardToLane, modifyPower, compactLane, discardCard } from './mutations';
import { calculateLanePower, findCardInState } from './selectors';
import { createCardInstance, createEmptyLane } from './factories';
import { PendingMove } from './planning';
import { queueTagTriggers, queueAbility } from './triggers';

// --- Initialization ---

export const createInitialGameState = (): GameState => {
  // 1. Setup Decks
  const p1Deck: CardInstance[] = PLAYER_DECK_IDS.map(id => {
    const def = CARDS.find(c => c.id === id)!;
    return createCardInstance(def, 'p1', 'DECK');
  }).sort(() => Math.random() - 0.5);

  const p2Deck: CardInstance[] = OPPONENT_DECK_IDS.map(id => {
    const def = CARDS.find(c => c.id === id)!;
    return createCardInstance(def, 'p2', 'DECK');
  }).sort(() => Math.random() - 0.5);

  // 2. Draw Initial Hands
  const p1Hand = p1Deck.splice(0, INITIAL_HAND_SIZE);
  const p2Hand = p2Deck.splice(0, INITIAL_HAND_SIZE);

  p1Hand.forEach(c => c.zone = 'HAND');
  p2Hand.forEach(c => c.zone = 'HAND');

  // 3. Setup Lanes
  const selectedLocs = [...LOCATION_DEFS].sort(() => Math.random() - 0.5).slice(0, 3);
  const lanes: [Lane, Lane, Lane] = [
      createEmptyLane(selectedLocs[0]), 
      createEmptyLane(selectedLocs[1]), 
      createEmptyLane(selectedLocs[2])
  ];

  // 4. Initial State Assembly
  const p1State: PlayerState = {
    energy: 1,
    stats: { destroyedCount: 0, destroyedPower: 0 },
    hand: p1Hand,
    deck: p1Deck,
    discardPile: [],
    destroyedPile: [],
    banishedPile: [],
  };
  const p2State: PlayerState = {
    energy: 1,
    stats: { destroyedCount: 0, destroyedPower: 0 },
    hand: p2Hand,
    deck: p2Deck,
    discardPile: [],
    destroyedPile: [],
    banishedPile: [],
  };

  let initialState: GameState = {
    turn: 1,
    maxTurns: MAX_TURNS,
    nextPlayOrder: 0,
    priority: 'p1', // Default
    players: {
      p1: p1State,
      p2: p2State,
    },
    lanes,
    winner: null,
    phase: 'planning',
    history: ['Game Started (Spec v1.4.0)'],
    eventQueue: [],
    executionQueue: [],
  };

  return applyContinuousEffects(initialState);
};

// --- Atomic Operations ---

export const executeDestroy = (state: GameState, instanceId: string): GameState => {
    let s = state;
    const lookup = findCardInState(s, instanceId);

    if (!lookup || lookup.location !== 'board') return s;

    const { card, laneIdx, slotIdx, owner } = lookup;

    // 1. Remove from Lane (Atomic)
    if (owner === 'p1') s.lanes[laneIdx!].p1Slots[slotIdx!] = null;
    else s.lanes[laneIdx!].p2Slots[slotIdx!] = null;

    // Close gap immediately
    compactLane(s.lanes[laneIdx!], owner);

    // 2. Update Card State
    card.zone = 'DESTROYED';
    card.laneIndex = null;
    card.slotIndex = null;

    // 3. Update Game Stats
    const playerState = s.players[owner];
    playerState.stats.destroyedCount++;
    playerState.stats.destroyedPower += card.totalPower;

    // 4. Visuals - Trigger both VFX and SFX for the "Pop" feel
    s = queueEvent(s, { type: 'VFX_PLAY', vfxId: 'vfx_explosion_small', laneIdx, slotIdx, playerId: owner });
    s = queueEvent(s, { type: 'SFX_PLAY', sfxId: 'sfx_destroy_digital' });

    // 5. Move to Pile
    playerState.destroyedPile.push(card);

    // 6. Queue OnDestroy Effects (Stack: LIFO)
    if (card.def.tags.includes('OnDestroy')) {
        s = queueAbility(s, card, 'OnDestroy');
    }

    s.history.push(`${card.def.name} was destroyed.`);
    return s;
};

// --- Execution Queue Processor (THE STACK) ---

/**
 * Executes EXACTLY ONE task from the stack.
 * Used by the UI loop to provide visual pacing (wait between steps).
 */
export const stepExecutionQueue = (state: GameState): GameState => {
    let s = cloneState(state);

    if (s.executionQueue.length === 0) return s;

    // POP from the end (Top of Stack)
    const task = s.executionQueue.pop()!;

    switch (task.type) {
        case 'TRIGGER_ABILITY': {
            const lookup = findCardInState(s, task.sourceId);

            if (lookup) {
                const { card, laneIdx, slotIdx, owner, location } = lookup;

                // ZONE INTEGRITY CHECK
                const isDestroyTrigger = task.triggerTag === 'OnDestroy';
                let isValid = false;
                if (isDestroyTrigger) {
                    isValid = location === 'board' || location === 'destroyed';
                } else {
                    isValid = location === 'board';
                }

                if (isValid) {
                    const ctx: EffectContext = {
                        player: owner,
                        laneIndex: laneIdx ?? 0, 
                        slotIndex: slotIdx ?? 0,
                        gameRegistry: CARDS,
                        actions: createActionSet() 
                    };

                    s = resolveEffect(card.def.effect, s, card, ctx);
                }
            }
            break;
        }

        case 'REVEAL_CARD': {
            const lookup = findCardInState(s, task.sourceId);

            // Only reveal if it's currently on the board
            if (lookup && lookup.location === 'board') {
                 const { card, laneIdx, slotIdx, owner } = lookup;

                 // Only reveal if currently hidden (idempotency)
                 if (!card.faceUp) {
                     card.faceUp = true;
                     s = applyContinuousEffects(s);

                     // Visuals
                     if (card.def.sfxOnReveal) {
                         s = queueEvent(s, { type: 'SFX_PLAY', sfxId: card.def.sfxOnReveal });
                     }
                     if (card.def.vfxOnReveal) {
                         s = queueEvent(s, { type: 'VFX_PLAY', vfxId: card.def.vfxOnReveal, laneIdx, slotIdx, playerId: owner });
                     }

                     // Trigger Ability
                     // This pushes the TRIGGER_ABILITY task to the stack, 
                     // so it executes immediately after this task finishes (LIFO).
                     if (card.def.tags.includes('OnReveal')) {
                         s = queueAbility(s, card, 'OnReveal');
                     }

                     s.history.push(`${card.def.name} was revealed (Summon).`);
                 }
            }
            break;
        }

        case 'EXECUTE_DISCARD': {
            const lookup = findCardInState(s, task.sourceId);
            if (lookup && lookup.location === 'hand') {
                    const { card, owner } = lookup;
                    const playerState = s.players[owner];

                    playerState.hand = playerState.hand.filter(c => c.instanceId !== task.sourceId);
                    playerState.discardPile.push(card);

                    card.zone = 'DISCARDED';
                    s = queueEvent(s, { type: 'SFX_PLAY', sfxId: 'sfx_ui_click' });
                    s.history.push(`${card.def.name} was discarded.`);
            }
            break;
        }

        case 'RUN_EFFECT': {
            const lookup = findCardInState(s, task.sourceId);
            if (lookup) {
                const { card, laneIdx, slotIdx, owner } = lookup;
                const ctx: EffectContext = {
                    player: owner,
                    laneIndex: laneIdx ?? 0, 
                    slotIndex: slotIdx ?? 0,
                    gameRegistry: CARDS,
                    actions: createActionSet(),
                    params: task.params
                };
                s = resolveEffect(task.effectId, s, card, ctx);
            }
            break;
        }
    }

    return applyContinuousEffects(s);
};

/**
 * Drains the entire queue synchronously. 
 * Use this for fast-forwarding or non-visual logic (like start of game).
 */
export const processExecutionQueue = (state: GameState): GameState => {
    let s = state;
    let ops = 0;
    const MAX_OPS = 100;

    while (s.executionQueue.length > 0 && ops < MAX_OPS) {
        s = stepExecutionQueue(s);
        ops++;
    }
    return s;
};

const createActionSet = (): ActionSet => ({
    destroyCard: (s, id) => executeDestroy(s, id),
    addCardToHand: (s, c) => addCardToHand(s, c),
    moveCard: (s, id, t) => moveCard(s, id, t),
    addCardToLane: (s, c, l) => addCardToLane(s, c, l),
    modifyPower: (s, id, d, src) => modifyPower(s, id, d, src),
    recalcState: (s) => applyContinuousEffects(s),
    playSfx: (s, sfxId) => queueEvent(s, { type: 'SFX_PLAY', sfxId })
});

// --- Phase Management ---

export const moveCardsToBoard = (state: GameState, p1Moves: PendingMove[], p2Moves: PendingMove[]): GameState => {
    let s = cloneState(state);
    p1Moves.forEach(move => { s = playCardFromHand(s, move.cardInstanceId, move.laneIdx); });
    p2Moves.forEach(move => { s = playCardFromHand(s, move.cardInstanceId, move.laneIdx); });
    return applyContinuousEffects(s);
};

export const getNextReveal = (state: GameState): { laneIdx: number, slotIdx: number, owner: PlayerID } | null => {
    const priorityPlayer = state.priority;
    const nonPriorityPlayer = state.priority === 'p1' ? 'p2' : 'p1';

    const unrevealedCards: CardInstance[] = [];

    // 1. Collect all unrevealed cards from the board
    for (const lane of state.lanes) {
        for (const card of [...lane.p1Slots, ...lane.p2Slots]) {
            if (card && !card.faceUp) {
                unrevealedCards.push(card);
            }
        }
    }

    if (unrevealedCards.length === 0) {
        return null;
    }

    // 2. Separate by player
    const priorityPlayerUnrevealed = unrevealedCards.filter(c => c.owner === priorityPlayer);
    const nonPriorityPlayerUnrevealed = unrevealedCards.filter(c => c.owner === nonPriorityPlayer);

    // 3. Sort each player's cards by playOrder (lower is earlier = First In First Out)
    priorityPlayerUnrevealed.sort((a, b) => (a.playOrder ?? Infinity) - (b.playOrder ?? Infinity));

    // FIX: Non-priority player should ALSO reveal in play order (First In First Out), not reverse order.
    // They just reveal AFTER the priority player is done.
    nonPriorityPlayerUnrevealed.sort((a, b) => (a.playOrder ?? Infinity) - (b.playOrder ?? Infinity));

    // 4. Determine the very next card to reveal
    const nextCardToReveal = priorityPlayerUnrevealed[0] ?? nonPriorityPlayerUnrevealed[0];

    if (nextCardToReveal) {
        return {
            laneIdx: nextCardToReveal.laneIndex!,
            slotIdx: nextCardToReveal.slotIndex!,
            owner: nextCardToReveal.owner
        };
    }

    return null;
};

// Updated: Only queues the reveal ability, does NOT drain queue automatically
export const revealCard = (state: GameState, laneIdx: number, slotIdx: number, owner: PlayerID): GameState => {
    let s = cloneState(state);
    const lane = s.lanes[laneIdx];
    const slot = owner === 'p1' ? lane.p1Slots[slotIdx] : lane.p2Slots[slotIdx];

    if (!slot) return s;

    slot.faceUp = true;
    s = applyContinuousEffects(s); 

    if (slot.def.tags.includes('OnReveal')) {
        s = queueAbility(s, slot, 'OnReveal');
    }

    if (slot.def.sfxOnReveal) {
        s = queueEvent(s, { type: 'SFX_PLAY', sfxId: slot.def.sfxOnReveal });
    }
    if (slot.def.vfxOnReveal) {
        s = queueEvent(s, { type: 'VFX_PLAY', vfxId: slot.def.vfxOnReveal, laneIdx, slotIdx, playerId: owner });
    }

    return s;
};

// Updated: Only queues, doesn't drain
export const resolveEndOfTurn = (state: GameState): GameState => {
    let s = cloneState(state);
    s = queueTagTriggers(s, 'EndOfTurn');
    return s;
};

// Updated: Only queues, doesn't drain
export const startNextTurn = (state: GameState): GameState => {
    let s = cloneState(state);

    s.turn++;
    s.players.p1.energy = Math.min(s.turn, MAX_ENERGY);
    s.players.p2.energy = Math.min(s.turn, MAX_ENERGY);

    s = drawCard(s, 'p1');
    s = drawCard(s, 'p2');

    const p1Power = s.lanes.reduce((acc, l) => acc + calculateLanePower(l, 'p1', s), 0);
    const p2Power = s.lanes.reduce((acc, l) => acc + calculateLanePower(l, 'p2', s), 0);

    if (p1Power > p2Power) s.priority = 'p1';
    else if (p2Power > p1Power) s.priority = 'p2';

    s = queueTagTriggers(s, 'StartOfTurn');

    s.phase = 'planning';
    return applyContinuousEffects(s);
};

export const calculateWinner = (state: GameState): PlayerID | 'draw' => {
    let p1Wins = 0;
    let p2Wins = 0;

    state.lanes.forEach(lane => {
        const p1 = calculateLanePower(lane, 'p1', state);
        const p2 = calculateLanePower(lane, 'p2', state);
        if (p1 > p2) p1Wins++;
        if (p2 > p1) p2Wins++;
    });

    if (p1Wins > p2Wins) return 'p1';
    if (p2Wins > p1Wins) return 'p2';

    const totalP1 = state.lanes.reduce((acc, l) => acc + calculateLanePower(l, 'p1', state), 0);
    const totalP2 = state.lanes.reduce((acc, l) => acc + calculateLanePower(l, 'p2', state), 0);

    if (totalP1 > totalP2) return 'p1';
    if (totalP2 > totalP1) return 'p2';

    return 'draw';
};

