import React, { useState, useEffect } from 'react';
import { AppShell } from './components/ui/AppShell';
import { MainMenuScreen } from './components/screens/MainMenuScreen';
import { GameScreen } from './components/screens/GameScreen';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { DeckScreen, ComicScreen } from './components/screens/PlaceholderScreens';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';

// --- Types & Config ---

type ScreenKey = 'MENU' | 'GAME' | 'DECK' | 'COMIC';

interface ScreenConfig {
    x: number; // Viewport Multiplier (0 = Center, 1 = Right, -1 = Left)
    y: number; // Viewport Multiplier (0 = Center, 1 = Down, -1 = Up)
    component: React.FC<any>;
}

// THE SPATIAL MAP
const WORLDS: Record<ScreenKey, ScreenConfig> = {
    MENU:  { x: 0,  y: 0,  component: MainMenuScreen },
    GAME:  { x: 1,  y: 0,  component: GameScreen },     // Right of Menu
    DECK:  { x: -1, y: 0,  component: DeckScreen },     // Left of Menu
    COMIC: { x: 0,  y: 1,  component: ComicScreen },    // Below Menu
};

export default function App() {
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  // Spatial State
  const [activeScreen, setActiveScreen] = useState<ScreenKey>('MENU');
  const [prevScreen, setPrevScreen] = useState<ScreenKey | null>(null);
  const [isTransitioning, setIsTransitioning] = useState(false);

  // App Initialization Logic
  useEffect(() => {
    const initApp = async () => {
      await preloadAssets((progress) => setLoadingProgress(progress));

      // Artificial delay for smooth intro
      setTimeout(() => {
        setIsLoading(false);
      }, 500);
    };
    initApp();
  }, []);

  // --- Navigation Engine ---

  const handleNavigate = (target: ScreenKey) => {
      if (target === activeScreen || isTransitioning) return;

      audio.playUiHover(); // Whoosh sound

      setPrevScreen(activeScreen);
      setActiveScreen(target);
      setIsTransitioning(true);

      // Culling Logic:
      // We keep the previous screen mounted for the duration of the transition (700ms)
      // plus a small buffer, then we unmount it to save DOM/Memory.
      setTimeout(() => {
          setIsTransitioning(false);
          setPrevScreen(null); 
      }, 750); // 700ms matches CSS duration
  };

  const handleStartGame = () => handleNavigate('GAME');

  // Calculate Camera Position
  const activeConfig = WORLDS[activeScreen];
  const cameraX = activeConfig.x * -100; // Invert for "Camera" movement
  const cameraY = activeConfig.y * -100;

  return (
    <AppShell>
      {/* 1. Global Loading Overlay (Z-Index Top) */}
      <div 
        className={`absolute inset-0 z-[100] transition-opacity duration-700 pointer-events-none ${isLoading ? 'opacity-100 pointer-events-auto' : 'opacity-0'}`}
      >
        {isLoading && <LoadingScreen progress={loadingProgress} />}
      </div>

      {/* 2. The World Container (Infinite Canvas) */}
      <div 
        className="w-full h-full relative transition-transform duration-700 ease-[cubic-bezier(0.25,1,0.5,1)] will-change-transform"
        style={{ transform: `translate3d(${cameraX}%, ${cameraY}%, 0)` }}
      >
          {/* 3. Screen Renderer */}
          {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
              // Culling Logic:
              // Render if it is the ACTIVE screen OR if it was the PREVIOUS screen and we are moving.
              const shouldRender = key === activeScreen || (isTransitioning && key === prevScreen);

              if (!shouldRender) return null;

              const config = WORLDS[key];
              const ScreenComponent = config.component;

              return (
                  <div 
                    key={key}
                    className="absolute w-full h-full top-0 left-0 overflow-hidden"
                    style={{ 
                        transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)` 
                    }}
                  >
                      <ScreenComponent 
                          onNavigate={handleNavigate} 
                          onExit={() => handleNavigate('MENU')}
                          onBack={() => handleNavigate('MENU')}
                          onStartGame={handleStartGame}
                      />
                  </div>
              );
          })}
      </div>

    </AppShell>
  );
}

import React from 'react';
import { useGameLogic } from './useGameLogic';
import { useDragAndDrop } from './useDragAndDrop';
import { useEventSystem } from './useEventSystem';
import { CardDefinition, CardInstance, LocationDefinition } from '../types';

export const useGameController = (onExit?: () => void) => {
    const logic = useGameLogic();

    // Mount Event System (Handles Audio & VFX)
    const eventSystem = useEventSystem(logic.events);

    // Initialize Drag and Drop
    const dnd = useDragAndDrop({
        gameState: logic.gameState,
        pendingMoves: logic.pendingMoves,
        isResolving: logic.isResolving,
        setPendingMoves: logic.setPendingMoves,
        setInspectingCard: logic.setInspectingCard,
        setInspectingLocation: logic.setInspectingLocation,
        setSelectedCardIdx: logic.setSelectedCardIdx,
        setShowUndoMenu: logic.setShowUndoMenu,
        onDrop: (success) => {
            if (success) eventSystem.playSnap();
        }
    });

    // --- Wrapped Actions (Logic + Audio) ---

    const handleCardClick = (idx: number, isDragging: boolean) => {
        if (!isDragging) {
            eventSystem.playClick();
            logic.handleCardClick(idx, isDragging);
        }
    };

    const handleLocationClick = (laneIdx: number) => {
        // Only play sound if we actually attempted an action (like playing a card)
        if (logic.selectedCardIdx !== null) {
            eventSystem.playSnap();
        }
        logic.handleLocationClick(laneIdx);
    };

    const handleUndoAll = () => {
        eventSystem.playClick();
        logic.handleUndoAll();
    };

    const handleEndTurn = () => {
        eventSystem.playClick();
        logic.handleEndTurn();
    };

    const handleResign = () => {
        eventSystem.playClick();
        logic.handleResign();
    };

    const restartGame = () => {
        eventSystem.playClick();
        logic.restartGame();
    };

    const handleExit = () => {
        eventSystem.playClick();
        if (onExit) onExit();
    };

    const toggleResults = (val: boolean) => {
        eventSystem.playClick();
        logic.setIsResultsHidden(val);
    };

    const closeInspector = () => {
        eventSystem.playClick();
        logic.setInspectingCard(null);
        logic.setInspectingLocation(null);
    };

    const inspectCard = (c: CardInstance | CardDefinition) => {
        eventSystem.playClick();
        logic.setInspectingCard(c);
    };

    const inspectLocation = (l: LocationDefinition) => {
        eventSystem.playClick();
        logic.setInspectingLocation(l);
    };

    const handleCardPointerDownHand = (e: React.PointerEvent, card: CardInstance, idx: number) => {
        dnd.handleCardPointerDown(e, card, { type: 'hand', index: idx });
    };

    const handleCardPointerDownLane = (e: React.PointerEvent, card: CardInstance, laneIdx: number) => {
        dnd.handleCardPointerDown(e, card, { type: 'lane', laneIdx });
    };

    return {
        // State
        gameState: logic.gameState,
        pendingMoves: logic.pendingMoves,
        isResolving: logic.isResolving,
        isWaiting: logic.isWaiting,
        currentEnergy: logic.currentEnergy,
        isResultsHidden: logic.isResultsHidden,
        showUndoMenu: logic.showUndoMenu,
        inspectingCard: logic.inspectingCard,
        inspectingLocation: logic.inspectingLocation,
        selectedCardIdx: logic.selectedCardIdx,
        dragState: dnd.dragState,
        activeVfx: eventSystem.activeVfx,

        // Logic Setters (only exposed if absolutely needed by UI, prefer actions)
        setShowUndoMenu: logic.setShowUndoMenu,

        // Actions
        actions: {
            handleCardClick,
            handleUndoAll,
            handleEndTurn,
            handleResign,
            restartGame,
            handleExit, // New Action
            toggleResults,
            closeInspector,
            inspectCard,
            inspectLocation,
            handleLocationClick,
            handleCardPointerDownHand,
            handleCardPointerDownLane
        }
    };
};

import React, { createContext, useContext, ReactNode } from 'react';
import { useGameController } from '../hooks/useGameController';

// Infer the return type from the hook
type GameController = ReturnType<typeof useGameController>;

const GameContext = createContext<GameController | null>(null);

export const GameProvider: React.FC<{ children: ReactNode; onExit?: () => void }> = ({ children, onExit }) => {
    const controller = useGameController(onExit);

    return (
        <GameContext.Provider value={controller}>
            {children}
        </GameContext.Provider>
    );
};

export const useGame = () => {
    const context = useContext(GameContext);
    if (!context) {
        throw new Error('useGame must be used within a GameProvider');
    }
    return context;
};

