                      <ScreenComponent 
                          onNavigate={handleNavigate} 
                          onExit={() => handleNavigate('MENU')}
                          onBack={() => handleNavigate('MENU')}
                          onStartGame={handleStartGame}
                      />
                  </div>
              );
          })}
      </div>

    </AppShell>
  );
}

