import React, { useState, useEffect } from 'react';
import { AppShell } from './components/ui/AppShell';
import { MainMenuScreen } from './components/screens/MainMenuScreen';
import { GameScreen } from './components/screens/GameScreen';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { 
    DeckScreen, 
    ComicScreen, 
    StoreScreen, 
    HistoryScreen, 
    InboxScreen 
} from './components/screens/PlaceholderScreens';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';

// --- Types & Config ---

type ScreenKey = 'MENU' | 'GAME' | 'DECK' | 'COMIC' | 'STORE' | 'HISTORY' | 'INBOX';

interface ScreenConfig {
    x: number; // Viewport Multiplier
    y: number; // Viewport Multiplier
    component: React.FC<any>;
}

// THE SPATIAL GRID
const WORLDS: Record<ScreenKey, ScreenConfig> = {
    // Top Row
    INBOX:   { x: -1, y: -1, component: InboxScreen },
    STORE:   { x: 0,  y: -1, component: StoreScreen },

    // Middle Row
    DECK:    { x: -1, y: 0,  component: DeckScreen },
    MENU:    { x: 0,  y: 0,  component: MainMenuScreen }, // Home / News
    GAME:    { x: 1,  y: 0,  component: GameScreen },

    // Bottom Row
    HISTORY: { x: -1, y: 1,  component: HistoryScreen },
    COMIC:   { x: 0,  y: 1,  component: ComicScreen },
};

export default function App() {
  // Auth State
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // Loading State
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  // Spatial State
  const [activeScreen, setActiveScreen] = useState<ScreenKey>('MENU');
  const [prevScreen, setPrevScreen] = useState<ScreenKey | null>(null);
  const [isTransitioning, setIsTransitioning] = useState(false);

  // App Initialization Logic
  useEffect(() => {
    const initApp = async () => {
      await preloadAssets((progress) => setLoadingProgress(progress));

      // Artificial delay for smooth intro
      setTimeout(() => {
        setIsLoading(false);
      }, 500);
    };
    initApp();
  }, []);

  // --- Auth Handler ---
  const handleLogin = () => {
      audio.playUiClick();
      setIsLoggedIn(true);
  };

  const handleLogout = () => {
      audio.playUiClick();
      setIsLoggedIn(false);
      setActiveScreen('MENU'); // Reset to menu on logout
  };

  // --- Navigation Engine ---

  const handleNavigate = (target: ScreenKey) => {
      if (target === activeScreen || isTransitioning) return;

      audio.playUiHover(); // Whoosh sound

      setPrevScreen(activeScreen);
      setActiveScreen(target);
      setIsTransitioning(true);

      // Culling Logic
      setTimeout(() => {
          setIsTransitioning(false);
          setPrevScreen(null); 
      }, 750); // Matches CSS duration
  };

  const handleStartGame = () => handleNavigate('GAME');

  // Calculate Camera Position
  const activeConfig = WORLDS[activeScreen];
  const cameraX = activeConfig.x * -100; // Invert for "Camera" movement
  const cameraY = activeConfig.y * -100;

  // --- RENDER FLOW ---

  // 1. Auth Gate
  if (!isLoggedIn) {
      return (
          <AppShell>
              <LoginScreen onLogin={handleLogin} />
          </AppShell>
      );
  }

  // 2. Main Application
  return (
    <AppShell>
      {/* Global Loading Overlay */}
      <div 
        className={`absolute inset-0 z-[100] transition-opacity duration-700 pointer-events-none ${isLoading ? 'opacity-100 pointer-events-auto' : 'opacity-0'}`}
      >
        {isLoading && <LoadingScreen progress={loadingProgress} />}
      </div>

      {/* The World Container (Infinite Canvas) */}
      <div 
        className="w-full h-full relative transition-transform duration-700 ease-[cubic-bezier(0.25,1,0.5,1)] will-change-transform"
        style={{ transform: `translate3d(${cameraX}%, ${cameraY}%, 0)` }}
      >
          {/* Screen Renderer */}
          {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
              // Culling Logic
              const shouldRender = key === activeScreen || (isTransitioning && key === prevScreen);

              if (!shouldRender) return null;

              const config = WORLDS[key];
              const ScreenComponent = config.component;

              return (
                  <div 
                    key={key}
                    className="absolute w-full h-full top-0 left-0 overflow-hidden"
                    style={{ 
                        transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)` 
                    }}
                  >
                      <ScreenComponent 
                          onNavigate={handleNavigate} 
                          onExit={() => handleNavigate('MENU')}
                          onBack={() => handleNavigate('MENU')}
                          onStartGame={handleStartGame}
                          onLogout={handleLogout}
                      />
                  </div>
              );
          })}
      </div>

      {/* Global Navigation Bar (Hidden in Game) */}
      {activeScreen !== 'GAME' && !isLoading && (
        <NavigationBar activeScreen={activeScreen} onNavigate={handleNavigate} />
      )}

    </AppShell>
  );
}

