import React from 'react';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    className = '',
    ...props 
}) => {
    // Styles mapping
    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_4px_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_4px_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_4px_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_4px_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_4px_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_4px_0_rgb(30,58,138)]",
    };

    const sizes = {
        sm: "h-8 text-xs",
        md: "h-10 text-sm",
        lg: "h-14 text-lg"
    };

    const widthClass = fullWidth ? 'w-full' : '';

    return (
        <div className={`relative group ${widthClass} ${sizes[size]} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-1 transition-all outline-none ${className}`}
                {...props}
            >
                {/* Background Shape */}
                <div className={`
                    absolute inset-0 bg-gradient-to-b border-2 rounded-lg skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200
                    ${variants[variant]}
                `}></div>

                {/* Content */}
                <div className="absolute inset-0 flex items-center justify-center z-20 skew-x-[-10deg]">
                    <span className="font-black text-white italic tracking-wider uppercase drop-shadow-md flex items-center gap-2">
                        {children}
                    </span>
                </div>
            </button>
        </div>
    );
};

