import React from 'react';
import { useGame } from '../contexts/GameContext';
import { HexButton } from './ui/HexButton';

export const ControlBar: React.FC = () => {
    const { 
        gameState, 
        isResolving, 
        isWaiting,
        currentEnergy, 
        isResultsHidden, 
        showUndoMenu, 
        actions, 
        setShowUndoMenu 
    } = useGame();

    return (
        <div className="h-12 px-2 pb-1 flex items-center justify-between relative bg-slate-950/50 gap-2 mt-1">
            {gameState.winner ? (
                /* GAME OVER CONTROLS */
                <>
                    <div className="flex-1">
                        <HexButton variant="secondary" onClick={() => actions.toggleResults(!isResultsHidden)}>
                            {isResultsHidden ? 'SHOW' : 'HIDE'}
                        </HexButton>
                    </div>
                    <div className="flex-1">
                        <HexButton variant="secondary" onClick={actions.handleExit}>
                            MENU
                        </HexButton>
                    </div>
                    <div className="flex-1">
                        <HexButton variant="success" onClick={actions.restartGame}>
                            RETRY
                        </HexButton>
                    </div>
                </>
            ) : (
                /* GAMEPLAY CONTROLS */
                <>
                    {/* RESIGN */}
                    <div className="min-w-[4.5rem]">
                        <HexButton variant="danger" onClick={actions.handleResign} disabled={gameState.winner !== null}>
                            RESIGN
                        </HexButton>
                    </div>

                    {/* ENERGY (Interactive with UNDO Popup) */}
                    <div className="relative flex flex-col items-center justify-center z-30 mx-2">

                        {/* Undo Menu Backdrop (for click outside) */}
                        {showUndoMenu && (
                            <div className="fixed inset-0 z-40" onClick={() => setShowUndoMenu(false)}></div>
                        )}

                        {/* Popup Undo Button */}
                        {showUndoMenu && (
                            <div className="absolute bottom-full mb-3 left-1/2 -translate-x-1/2 z-50 animate-pop min-w-[6rem]">
                                <HexButton 
                                    variant="blue" 
                                    onClick={actions.handleUndoAll}
                                >
                                    UNDO ALL
                                </HexButton>
                                <div className="w-2 h-2 bg-blue-600 rotate-45 absolute -bottom-1 left-1/2 -translate-x-1/2 border-r border-b border-blue-400"></div>
                            </div>
                        )}

                        {/* Energy Orb */}
                        <div 
                            onClick={() => {
                                if (gameState.phase === 'planning' && !isResolving && !isWaiting) {
                                    setShowUndoMenu(!showUndoMenu);
                                }
                            }}
                            className={`
                                w-10 h-10 rounded-full bg-gradient-to-br from-indigo-600 to-blue-800 border-2 border-indigo-300 shadow-[0_0_15px_rgba(79,70,229,0.5)] flex items-center justify-center relative transition-transform cursor-pointer
                                ${showUndoMenu ? 'scale-110 ring-2 ring-white' : 'active:scale-95 hover:scale-105'}
                                ${isResolving || isWaiting ? 'opacity-50 pointer-events-none' : ''}
                            `}
                        >
                            <span className="text-sm font-black text-white select-none">{currentEnergy}</span>
                        </div>
                    </div>

                    {/* END TURN */}
                    <div className="flex-1">
                        <HexButton 
                            variant="primary" 
                            onClick={actions.handleEndTurn} 
                            disabled={gameState.winner !== null || isResolving || isWaiting}
                        >
                            {isResolving ? 'PLAYING...' : (isWaiting ? 'OPPONENT...' : 'END TURN')}
                        </HexButton>
                    </div>
                </>
            )}
        </div>
    );
};

