// --- STORE (SCROLLING) ---
export const StoreScreen: React.FC<PlaceholderProps> = () => {

    const scrollTo = (id: string) => {
        document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    };

    // Helper for rendering Gold Icons inside Credit buttons
    const GoldIcon = ({ size = 'md' }: { size?: 'sm'|'md' }) => (
        <div className={`${size === 'sm' ? 'w-3 h-3' : 'w-4 h-4'} rounded-sm bg-amber-400 shadow-[0_0_5px_rgba(251,191,36,0.8)] border border-amber-200`}></div>
    );

    // --- RENDER HELPERS ---

    const renderCreditItem = (amount: number, cost: number | 'FREE', i: number) => {
        const isFree = cost === 'FREE';

        return (
            <div key={i} className="bg-slate-900 border border-slate-800 rounded-xl p-2 flex flex-col items-center justify-between gap-1 h-full relative group">
                {/* Amount */}
                <div className="mt-2 font-black text-white text-lg leading-none text-center drop-shadow-md italic">
                    {amount}
                </div>
                <div className="text-[0.6rem] font-bold text-blue-400 uppercase tracking-wider mb-2">Credits</div>

                {/* Visual */}
                <div className="w-full flex-1 flex items-center justify-center py-2">
                    <div className="w-12 h-12 rounded-full bg-blue-500/10 flex items-center justify-center border border-blue-500/30 shadow-[0_0_15px_rgba(59,130,246,0.2)]">
                        <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-blue-600 to-blue-400 shadow-lg border border-blue-300"></div>
                    </div>
                </div>

                {/* Button */}
                <div className="w-full mt-auto">
                    <HexButton variant={isFree ? 'success' : 'secondary'} size="sm" fullWidth>
                        {isFree ? "FREE" : <><GoldIcon size="sm" /> {cost}</>}
                    </HexButton>
                </div>
            </div>
        );
    };

    const renderGoldVisuals = (index: number) => {
        const smallClass = "w-4 h-2.5 bg-gradient-to-br from-yellow-300 to-amber-500 border border-yellow-100 rounded-[1px] shadow-sm transform rotate-12 mx-0.5 my-0.5";
        const bigClass = "w-9 h-5 bg-gradient-to-br from-amber-300 via-yellow-400 to-amber-600 border border-amber-100 rounded-sm shadow-md transform -rotate-6 mx-1 my-1";

        // Manual config based on request
        // 1, 2, 4, 8, 13, 27 (Modified: 13 -> 1 Big+6, 27 -> 4 Big)
        switch(index) {
            case 0: // 300g (1 bar)
                return <div className={smallClass}></div>;
            case 1: // 700g (2 bars)
                return <div className="flex">{Array(2).fill(0).map((_,i) => <div key={i} className={smallClass}></div>)}</div>;
            case 2: // 1450g (4 bars)
                return <div className="grid grid-cols-2 gap-0.5">{Array(4).fill(0).map((_,i) => <div key={i} className={smallClass}></div>)}</div>;
            case 3: // 2600g (8 bars)
                return <div className="grid grid-cols-3 gap-0.5 px-2">{Array(8).fill(0).map((_,i) => <div key={i} className={smallClass}></div>)}</div>;
            case 4: // 3850g (1 Big + 6 Small = ~3800ish representation)
                return (
                    <div className="flex flex-col items-center">
                        <div className={bigClass}></div>
                        <div className="flex flex-wrap justify-center -mt-1 relative z-10">
                            {Array(6).fill(0).map((_,i) => <div key={i} className={smallClass}></div>)}
                        </div>
                    </div>
                );
            case 5: // 8000g (4 Big Bars)
                return <div className="grid grid-cols-2 gap-1">{Array(4).fill(0).map((_,i) => <div key={i} className={bigClass}></div>)}</div>;
            default: return null;
        }
    };

    const renderGoldItem = (amount: number, price: string, badge: string | null, i: number) => {
        return (
            <div key={i} className="bg-slate-900 border border-slate-800 rounded-xl p-2 flex flex-col items-center justify-between h-full relative group overflow-visible">
                {/* Badge (Flush Top Right of Container) */}
                {badge && (
                    <div className="absolute -top-1 -right-1 z-30 bg-red-600 border border-red-400 text-white text-[0.5rem] font-black px-2 py-0.5 rounded shadow-lg uppercase tracking-tight skew-x-[-10deg]">
                        {badge}
                    </div>
                )}

                {/* Amount Header */}
                <div className="mt-2 flex items-center justify-center gap-2 w-full">
                    <div className="font-black text-amber-100 text-lg leading-none text-center drop-shadow-md italic">
                        {amount}
                    </div>
                </div>
                <div className="text-[0.6rem] font-bold text-amber-500/80 uppercase tracking-wider mb-1">Gold</div>

                {/* Visual */}
                <div className="w-full flex-1 flex items-center justify-center py-2 relative min-h-[3.5rem]">
                     <div className="absolute inset-0 bg-amber-500/5 blur-xl rounded-full scale-75"></div>
                     <div className="relative z-10">
                        {renderGoldVisuals(i)}
                     </div>
                </div>

                {/* Button (Purple Hex Style) - Clean */}
                <div className="w-full mt-1">
                    <HexButton variant="primary" fullWidth size="md">
                        {price}
                    </HexButton>
                </div>
            </div>
        );
    };

    return (
        <div className="w-full h-full bg-slate-950 flex flex-col overflow-y-auto">
            <StandardHeader 
                title="Store" 
                showCurrency={true}
                onCreditClick={() => scrollTo('store-credits')}
                onGoldClick={() => scrollTo('store-gold')}
            />

            <div className="p-4 space-y-8 pb-32"> 
                {/* Daily Offer */}
                <div className="w-full aspect-video rounded-2xl bg-gradient-to-br from-emerald-900 to-slate-900 border border-emerald-700/50 relative overflow-hidden p-6 flex flex-col justify-end">
                    <div className="absolute top-2 right-2 bg-red-600 text-white text-xs font-bold px-2 py-1 rounded">-50% OFF</div>
                    <h2 className="text-2xl font-black text-white relative z-10">STARTER BUNDLE</h2>
                    <p className="text-emerald-200 text-sm relative z-10 mb-2">Get 500 Credits + Variant Card</p>
                    <div className="w-32 relative z-10">
                        <HexButton variant="success" fullWidth>
                             $4.99 USD
                        </HexButton>
                    </div>
                </div>

                {/* Credits Section */}
                <div id="store-credits" className="scroll-mt-24">
                     <h3 className="text-blue-400 font-bold text-xs tracking-widest uppercase mb-3 flex items-center gap-2">
                         <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                         Credits
                     </h3>
                     <div className="grid grid-cols-3 gap-3">
                         {renderCreditItem(25, 'FREE', 0)}
                         {renderCreditItem(500, 400, 1)}
                         {renderCreditItem(1500, 1200, 2)}
                     </div>
                </div>

                {/* Gold Section */}
                <div id="store-gold" className="scroll-mt-24">
                     <h3 className="text-amber-400 font-bold text-xs tracking-widest uppercase mb-3 flex items-center gap-2">
                         <div className="w-2 h-2 rounded-full bg-amber-500"></div>
                         Gold
                     </h3>
                     <div className="grid grid-cols-3 gap-3">
                         {renderGoldItem(300, '$4.99', null, 0)}
                         {renderGoldItem(700, '$9.99', null, 1)}
                         {renderGoldItem(1450, '$19.99', 'DOUBLE', 2)}
                         {renderGoldItem(2600, '$34.99', '+25%', 3)}
                         {renderGoldItem(3850, '$49.99', '+35%', 4)}
                         {renderGoldItem(8000, '$99.99', 'BEST', 5)}
                     </div>
                </div>

                <div className="h-10 text-center text-slate-600 text-xs mt-8">End of Catalog</div>
            </div>
        </div>
    );
};

