// THE SPATIAL GRID CONFIGURATION
export const WORLDS: Record<ScreenKey, ScreenConfig> = {
    // Top Row
    INBOX:   { x: -1, y: -1, component: InboxScreen },
    STORE:   { x: 0,  y: -1, component: StoreScreen },

    // Middle Row
    DECK:    { x: -1, y: 0,  component: DeckScreen },
    MENU:    { x: 0,  y: 0,  component: MainMenuScreen }, // Home
    GAME:    { x: 1,  y: 0,  component: GameScreen },

