export const useSpatialNavigation = () => {
    const [activeScreen, setActiveScreen] = useState<ScreenKey>('MENU');
    const [prevScreen, setPrevScreen] = useState<ScreenKey | null>(null);
    const [isTransitioning, setIsTransitioning] = useState(false);

    const navigateTo = (target: ScreenKey) => {
        if (target === activeScreen || isTransitioning) return;

        audio.playUiHover(); // Transition sound

        setPrevScreen(activeScreen);
        setActiveScreen(target);
        setIsTransitioning(true);

        // Culling Logic: Stop rendering the previous screen after animation completes
        // This matches the CSS duration (700ms) plus a small buffer
        setTimeout(() => {
            setIsTransitioning(false);
            setPrevScreen(null); 
        }, 750); 
    };

    const resetToMenu = () => {
        setActiveScreen('MENU');
        setPrevScreen(null);
        setIsTransitioning(false);
    };

    // Calculate Camera Position
    const activeConfig = WORLDS[activeScreen];
    const cameraX = activeConfig.x * -100; // Invert for "Camera" movement
    const cameraY = activeConfig.y * -100;

    const containerStyle = { 
        transform: `translate3d(${cameraX}%, ${cameraY}%, 0)` 
    };

    return {
        activeScreen,
        prevScreen,
        isTransitioning,
        containerStyle,
        navigateTo,
        resetToMenu,
        WORLDS // Exposed for rendering list
    };
};

