import React from 'react';

interface CardBadgeProps {
    value: number;
    type: 'cost' | 'power';
    size: 'xs' | 'sm' | 'md' | 'lg';
    colorClass: string;
    variant: 'default' | 'board';
}

const badgeConfig = {
    xs: { 
        dims: 'w-5 h-5', 
        text: 'text-[0.65rem]', 
        radiusTL: 'rounded-br', 
        radiusTR: 'rounded-bl' 
    },
    sm: { 
        dims: 'w-6 h-6', 
        text: 'text-xs', 
        radiusTL: 'rounded-br', 
        radiusTR: 'rounded-bl' 
    },
    md: { 
        dims: 'w-7 h-7', 
        text: 'text-sm', 
        radiusTL: 'rounded-br-lg', 
        radiusTR: 'rounded-bl-lg' 
    },
    lg: { 
        dims: 'w-14 h-14', 
        text: 'text-3xl', 
        radiusTL: 'rounded-br-2xl', 
        radiusTR: 'rounded-bl-2xl' 
    },
};

export const CardBadge: React.FC<CardBadgeProps> = ({ value, type, size, colorClass, variant }) => {
    // Requirement: Do not display cost on board
    if (type === 'cost' && variant === 'board') return null;

    const b = badgeConfig[size];
    const position = type === 'cost' ? 'top-0 left-0' : 'top-0 right-0';
    const radius = type === 'cost' ? b.radiusTL : b.radiusTR;

    // Border Width Logic
    const w = size === 'lg' ? '4' : (size === 'md' ? '2' : '');
    const suffix = w ? `-${w}` : '';

    // Border Side Logic
    const borderStyle = type === 'cost' 
        ? `border-r${suffix} border-b${suffix}` 
        : `border-l${suffix} border-b${suffix}`;

    return (
      <div className={`absolute ${position} bg-slate-900 ${colorClass} font-black ${radius} ${borderStyle} border-slate-700 z-10 shadow-lg flex items-center justify-center leading-none ${b.dims} ${b.text}`}>
        {value}
      </div>
    );
};

import React from 'react';
import { CardInstance, CardDefinition } from '../types';
import { CardBadge } from './card/CardBadge';

interface CardProps {
  card: CardInstance | CardDefinition;
  onClick?: () => void;
  isPlayable?: boolean;
  isSelected?: boolean;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  variant?: 'default' | 'board';
  hidden?: boolean;
  onPointerDown?: (e: React.PointerEvent) => void;
  isDragging?: boolean;
}

export const Card: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  variant = 'default', 
  hidden, 
  onPointerDown,
  isDragging
}) => {
  // Safe accessors
  const isInstance = (c: any): c is CardInstance => 'instanceId' in c;
  const def = isInstance(card) ? card.def : card;

  // Styles
  // ALL sizes must respect aspect-[5/7]
  const sizeClasses = {
    xs: 'w-full aspect-[5/7] text-[0.5rem] rounded-md border', 
    sm: 'w-16 aspect-[5/7] text-[0.625rem] rounded-md border-2',
    md: 'w-20 aspect-[5/7] text-xs rounded-lg border-2',
    lg: 'w-64 aspect-[5/7] text-lg rounded-2xl border-4', 
  };
  const currentSizeClass = sizeClasses[size];

  if (hidden) {
      return (
        <div 
            className={`${currentSizeClass} bg-indigo-900 border-indigo-400 shadow-md flex items-center justify-center relative touch-none`}
        >
            <div className="w-1/3 h-1/3 rounded-full bg-indigo-500 animate-pulse"></div>
        </div>
      )
  }

  // Border Color based on Ability Tag
  let borderColor = 'border-gray-600';
  if (def.tags.includes('OnReveal')) borderColor = 'border-yellow-500';
  else if (def.tags.includes('Ongoing')) borderColor = 'border-blue-500';
  else if (def.tags.includes('Destroy')) borderColor = 'border-red-500';
  else if (def.tags.includes('Move')) borderColor = 'border-purple-500';

  // Stats Logic
  const basePower = def.basePower;
  const currentDisplayPower = isInstance(card) ? card.totalPower : basePower;

  const baseCost = def.baseCost;
  const currentDisplayCost = isInstance(card) ? card.totalCost : baseCost;

  const powerColor = currentDisplayPower > basePower ? 'text-green-400' : (currentDisplayPower < basePower ? 'text-red-400' : 'text-white');
  const costColor = currentDisplayCost < baseCost ? 'text-green-400' : (currentDisplayCost > baseCost ? 'text-red-400' : 'text-white');

  const opacityClass = isDragging ? 'opacity-50' : 'opacity-100';
  const cursorClass = onPointerDown || onClick ? 'cursor-grab active:cursor-grabbing' : '';
  const borderClass = size === 'xs' ? 'border' : (size === 'lg' ? 'border-4' : 'border-2');

  // Board Variant
  if (variant === 'board') {
    return (
      <div
        onPointerDown={onPointerDown}
        onClick={onClick}
        className={`w-full aspect-[5/7] ${borderColor} ${borderClass} ${opacityClass} bg-slate-800 relative overflow-hidden shadow-md select-none touch-none ${cursorClass} ${size === 'xs' ? 'rounded-md' : 'rounded-sm'}`}
      >
        <img src={def.imageUrl} alt={def.name} className="absolute inset-0 w-full h-full object-cover" />

        <CardBadge value={currentDisplayCost} type="cost" size={size} colorClass={costColor} variant={variant} />
        <CardBadge value={currentDisplayPower} type="power" size={size} colorClass={powerColor} variant={variant} />

        <div className="absolute bottom-0 w-full h-1/4 bg-gradient-to-t from-black/60 to-transparent pointer-events-none"></div>
      </div>
    );
  }

  // Large Full-Art Variant (Inspector)
  if (size === 'lg') {
      return (
        <div className={`${currentSizeClass} ${borderColor} ${opacityClass} bg-slate-800 flex flex-col relative overflow-hidden shadow-2xl select-none touch-none`}>

          {/* Full Image Area */}
          <img src={def.imageUrl} alt={def.name} className="absolute inset-0 object-cover w-full h-full" />

          <CardBadge value={currentDisplayCost} type="cost" size={size} colorClass={costColor} variant={variant} />
          <CardBadge value={currentDisplayPower} type="power" size={size} colorClass={powerColor} variant={variant} />

          {/* Name Plate (Bottom Overlay) */}
          <div className="absolute bottom-0 inset-x-0 pb-4 pt-16 bg-gradient-to-t from-black via-black/60 to-transparent flex justify-center items-end">
             <div className="font-black text-center truncate leading-tight text-white text-3xl tracking-wider uppercase px-2 drop-shadow-lg">
               {def.name}
             </div>
          </div>
        </div>
      );
  }

  // Default Layout (Hand/Collection)
  return (
    <div
      onPointerDown={onPointerDown}
      onClick={onClick}
      className={`${currentSizeClass} ${borderColor} ${opacityClass} bg-slate-800 flex flex-col relative overflow-hidden shadow-lg select-none transition-opacity duration-200 touch-none ${cursorClass}`}
    >
      <CardBadge value={currentDisplayCost} type="cost" size={size} colorClass={costColor} variant={variant} />
      <CardBadge value={currentDisplayPower} type="power" size={size} colorClass={powerColor} variant={variant} />

      {/* Image */}
      <div className="flex-1 w-full overflow-hidden bg-black relative">
        <img src={def.imageUrl} alt={def.name} className="absolute inset-0 object-cover w-full h-full opacity-90 pointer-events-none" />
      </div>

      {/* Info */}
      <div className="w-full flex flex-col justify-center bg-gradient-to-b from-slate-800 to-slate-900 h-auto py-1">
        <div className="font-bold text-center truncate leading-tight text-white text-[0.625rem]">
          {def.name}
        </div>
      </div>
    </div>
  );
};

