import React from 'react';
import { CardInstance, CardDefinition } from '../../types';
import { Card } from '../Card';

interface LaneGridProps {
    slots: (CardInstance | null)[];
    isOpponent: boolean;
    pendingCards: { card: CardInstance, handIndex: number }[]; 
    lastPendingCardId: string | null;
    draggingCardId?: string;
    onInspectCard: (card: CardInstance | CardDefinition) => void;
    onCardPointerDown: (e: React.PointerEvent, card: CardInstance) => void;
}

export const LaneGrid: React.FC<LaneGridProps> = ({ 
    slots, 
    isOpponent, 
    pendingCards, 
    lastPendingCardId, 
    draggingCardId,
    onInspectCard,
    onCardPointerDown
}) => {
    // ABSOLUTE POSITIONING STRATEGY
    // Slot 0: Top Left (0,0)
    // Slot 1: Top Right (50,0)
    // Slot 2: Bottom Left (0,50)
    // Slot 3: Bottom Right (50,50)

    const getPosition = (slotIdx: number, isOpp: boolean) => {
        if (!isOpp) {
            return {
                top: slotIdx < 2 ? '0%' : '50%',
                left: (slotIdx % 2 === 0) ? '0%' : '50%',
                zIndex: slotIdx + 10 
            };
        } else {
            // Mirrored for P2 (Cards spawn near center and fill outwards visually)
            return {
                top: slotIdx < 2 ? '50%' : '0%',
                left: (slotIdx % 2 === 0) ? '50%' : '0%',
                zIndex: slotIdx + 10
            };
        }
    };

    return (
        <div className="relative w-full h-full isolate">
            {/* Grid Guides */}
            <div className="absolute inset-0 grid grid-cols-2 grid-rows-2 gap-1 pointer-events-none opacity-20">
                {[0,1,2,3].map(i => (
                    <div key={i} className="rounded-md border border-slate-500/30 bg-slate-800/20 w-full h-full"></div>
                ))}
            </div>

            {/* Render Cards */}
            {slots.map((card, currentSlotIdx) => {
                if (!card) return null;

                // Pending Logic (only applies to Player 1)
                const isPending = !isOpponent && pendingCards.some(p => p.card.instanceId === card.instanceId);
                const isLocked = isPending && lastPendingCardId && card.instanceId !== lastPendingCardId;
                const isDraggingThis = card.instanceId === draggingCardId;

                const { top, left, zIndex } = getPosition(currentSlotIdx, isOpponent);

                return (
                    <div 
                      key={card.instanceId}
                      className={`
                          absolute w-[48%] h-[48%] transition-all duration-300 ease-[cubic-bezier(0.34,1.56,0.64,1)]
                          ${isDraggingThis ? 'opacity-0' : ''}
                      `}
                      style={{ top, left, zIndex }}
                    >
                        <div className={`w-full h-full ${isPending ? 'opacity-80' : ''} ${isLocked ? '!opacity-60 contrast-75 grayscale-[0.5]' : ''}`}>
                            <Card 
                              card={card} 
                              hidden={!card.faceUp} 
                              size="xs"
                              variant="board"
                              onPointerDown={isPending && !isLocked ? (e) => onCardPointerDown(e, card) : undefined}
                              onClick={() => card.faceUp && onInspectCard(card)}
                            />
                        </div>
                    </div>
                );
            })}
        </div>
    );
};

import React from 'react';
import { Lane, GameState, CardInstance, CardDefinition, LocationDefinition } from '../types';
import { LocationCard } from './LocationCard';
import { calculateLanePower, getProjectedLaneState } from '../services/selectors';
import { LaneGrid } from './board/LaneGrid';

interface LocationProps {
  lane: Lane;
  laneIndex: number;
  gameState: GameState;
  onSelectForPlay: () => void;
  isPlayable: boolean;
  selectedCardCost: number | null;
  pendingCards: { card: CardInstance, handIndex: number }[]; 
  lastPendingCardId: string | null;
  onInspectCard: (card: CardInstance | CardDefinition) => void;
  onInspectLocation: (location: LocationDefinition) => void;
  onCardPointerDown: (e: React.PointerEvent, card: CardInstance) => void;
  draggingCardId?: string;
}

export const Location: React.FC<LocationProps> = ({ 
    lane, laneIndex, gameState, onSelectForPlay, isPlayable, 
    pendingCards, lastPendingCardId, onInspectCard, onInspectLocation, onCardPointerDown, draggingCardId
}) => {

  const playerPower = calculateLanePower(lane, 'p1', gameState);
  const opponentPower = calculateLanePower(lane, 'p2', gameState);

  const playerWinning = playerPower > opponentPower;
  const opponentWinning = opponentPower > playerPower;

  const playerBadgeClass = playerWinning ? 'bg-green-900 border-green-500' : 'bg-red-900 border-red-500';
  const opponentBadgeClass = opponentWinning ? 'bg-green-900 border-green-500' : 'bg-red-900 border-red-500';
  const winningClass = playerWinning 
    ? 'border-green-500/30 bg-green-900/10' 
    : (opponentWinning ? 'border-red-500/30 bg-red-900/10' : 'border-slate-700');

  const p1ProjectedSlots = getProjectedLaneState(gameState, laneIndex, pendingCards);
  const p2Slots = lane.p2Slots;

  return (
    <div 
        className={`flex-1 flex flex-col ${winningClass} relative transition-colors duration-500`}
        data-drop-zone="lane"
        data-lane-idx={laneIndex}
    >
      {/* OPPONENT GRID (Top) */}
      <div className="w-full flex-none flex items-start justify-center pt-1">
          <div className="w-full p-0.5 aspect-[10/14]">
             <LaneGrid 
                slots={p2Slots} 
                isOpponent={true} 
                pendingCards={[]} 
                lastPendingCardId={null}
                onInspectCard={onInspectCard}
                onCardPointerDown={() => {}} // No interaction with enemy cards
             />
          </div>
      </div>

      {/* CENTER (Power & Location Card) */}
      <div className="w-full px-1 z-10 flex-none flex items-center justify-center relative my-3">
         <div className={`absolute -top-3 left-1/2 -translate-x-1/2 text-white rounded-full w-6 h-6 text-xs flex items-center justify-center font-bold border-2 z-30 shadow-lg ${opponentBadgeClass}`}>
            {opponentPower}
         </div>

         <LocationCard 
            location={lane.location.def} 
            size="sm" 
            onClick={() => onInspectLocation(lane.location.def)}
         />

         <div className={`absolute -bottom-3 left-1/2 -translate-x-1/2 text-white rounded-full w-6 h-6 text-xs flex items-center justify-center font-bold border-2 z-30 shadow-lg ${playerBadgeClass}`}>
            {playerPower}
         </div>
      </div>

      {/* PLAYER GRID (Bottom) */}
      <div 
        onClick={isPlayable ? onSelectForPlay : undefined}
        className={`w-full flex-none flex items-end justify-center relative transition-all pb-1
            ${isPlayable ? 'bg-green-500/10 cursor-pointer hover:bg-green-500/20' : ''}
        `}
      >
         <div className="w-full p-0.5 aspect-[10/14] z-10">
            <LaneGrid 
                slots={p1ProjectedSlots} 
                isOpponent={false} 
                pendingCards={pendingCards} 
                lastPendingCardId={lastPendingCardId}
                draggingCardId={draggingCardId}
                onInspectCard={onInspectCard}
                onCardPointerDown={onCardPointerDown}
             />
         </div>
      </div>
    </div>
  );
};

import React from 'react';
import { StatModifier } from '../../types';

interface StatHistoryProps {
    modifiers: StatModifier[];
    type: 'cost' | 'power';
    side: 'left' | 'right';
}

export const StatHistory: React.FC<StatHistoryProps> = ({ modifiers, type, side }) => {

    const renderStatModifier = (m: StatModifier) => {
        const isBase = m.type === 'BASE';
        let valueColor = 'text-white';
        let sign = '';

        if (!isBase) {
            if (type === 'power') {
                // Power: +Green (Good), -Red (Bad)
                if (m.value > 0) { valueColor = 'text-green-400'; sign = '+'; }
                if (m.value < 0) { valueColor = 'text-red-400'; }
            } else {
                // Cost: +Red (Bad), -Green (Good)
                if (m.value > 0) { valueColor = 'text-red-400'; sign = '+'; }
                if (m.value < 0) { valueColor = 'text-green-400'; }
            }
        }

        return (
            <div className="flex justify-between items-center w-full mb-1 last:mb-0 bg-black/20 rounded px-1 py-0.5">
                <span className="text-slate-400 text-[0.65rem] font-bold uppercase tracking-wider truncate max-w-[8rem]">
                    {m.source}
                </span>
                <span className={`font-black text-sm ${valueColor}`}>
                    {sign}{m.value}
                </span>
            </div>
        );
    };

    // Positioning Classes
    const positionClass = side === 'left' 
        ? "bottom-full right-[52%] origin-bottom-right" 
        : "bottom-full left-[52%] origin-bottom-left";

    return (
        <div className={`absolute ${positionClass} mb-3 w-48 animate-slide-up pointer-events-auto`}>
             <div className="bg-slate-900/95 border border-slate-600 rounded-xl p-2 shadow-2xl flex flex-col max-h-48 overflow-y-auto">
                <div className="flex flex-col gap-0.5">
                    {modifiers.map((m, i) => (
                        <React.Fragment key={i}>
                            {renderStatModifier(m)}
                        </React.Fragment>
                    ))}
                </div>
             </div>
        </div>
    );
};

import React from 'react';
import { useGame } from '../contexts/GameContext';
import { CardInstance, CardDefinition } from '../types';
import { Card } from './Card';
import { LocationCard } from './LocationCard';
import { StatHistory } from './inspector/StatHistory';

export const InspectorOverlay: React.FC = () => {
    const { inspectingCard, inspectingLocation, actions } = useGame();

    if (!inspectingCard && !inspectingLocation) return null;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;
    const isInstanceWithStats = (c: any): c is CardInstance => c && 'costModifiers' in c && 'powerModifiers' in c;

    const getCardText = () => {
        if (!inspectingCard) return '';
        const def = isInstance(inspectingCard) ? inspectingCard.def : inspectingCard;
        return isInstance(inspectingCard) ? inspectingCard.currentText : def.baseText;
    };

    // Helper for rendering formatted text (Simple Inline Style)
    const renderCardText = (text: string) => {
        const parts = text.split(':');
        const keywords = ['On Reveal', 'On Going', 'On Destroy', 'On Move', 'On Discard'];

        if (parts.length > 1 && keywords.some(k => parts[0].trim().includes(k))) {
           return (
             <span>
               <span className="text-yellow-400 font-black uppercase tracking-wider mr-1">{parts[0]}:</span>
               <span className="font-medium text-white/90 shadow-black drop-shadow-sm">{parts.slice(1).join(':')}</span>
             </span>
           );
        }
        return <span className="font-bold text-white/90 shadow-black drop-shadow-sm">{text}</span>;
    };

    return (
        <div 
            className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-pop overflow-y-auto touch-none"
            onClick={actions.closeInspector}
        >
            {/* Card Inspector Content */}
            {inspectingCard && (
                <div className="flex flex-col items-center w-full max-w-[20rem] mt-12"> 

                    <div className="relative z-40 scale-110 mb-6 shadow-[0_0_50px_rgba(0,0,0,0.5)]">

                        {/* STATS HISTORY OVERLAYS */}
                        {isInstanceWithStats(inspectingCard) && (
                            <>
                                <StatHistory modifiers={inspectingCard.costModifiers} type="cost" side="left" />
                                <StatHistory modifiers={inspectingCard.powerModifiers} type="power" side="right" />
                            </>
                        )}

                        <Card card={inspectingCard} size="lg" />
                    </div>

                    {/* Bottom: Description Text Only */}
                    <div className="w-full max-w-xs text-center leading-relaxed animate-slide-up px-2 select-text">
                         {renderCardText(getCardText())}
                    </div>
                </div>
            )}

            {/* Location Inspector Content */}
            {inspectingLocation && (
                <div className="relative z-40 scale-125 animate-pop drop-shadow-2xl">
                    <LocationCard location={inspectingLocation} size="lg" />
                </div>
            )}

            <div className="fixed bottom-8 text-white/30 text-xs tracking-[0.2em] uppercase font-bold animate-pulse pointer-events-none">
                Tap background to close
            </div>

            <style>{`
                @keyframes slide-up {
                    from { opacity: 0; transform: translateY(10px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                .animate-slide-up {
                    animation: slide-up 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </div>
    );
};

