import React from 'react';
import { CardInstance, CardDefinition } from '../types';
import { CardBoardView } from './card/CardBoardView';
import { CardFullArtView } from './card/CardFullArtView';
import { CardStandardView } from './card/CardStandardView';

interface CardProps {
  card: CardInstance | CardDefinition;
  onClick?: () => void;
  isPlayable?: boolean;
  isSelected?: boolean;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  variant?: 'default' | 'board';
  hidden?: boolean;
  onPointerDown?: (e: React.PointerEvent) => void;
  isDragging?: boolean;
}

export const Card: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  variant = 'default', 
  hidden, 
  onPointerDown,
  isDragging
}) => {
  // Safe accessors
  const isInstance = (c: any): c is CardInstance => 'instanceId' in c;
  const def = isInstance(card) ? card.def : card;

  // Styles
  const sizeClasses = {
    xs: 'w-full aspect-[5/7] text-[0.5rem] rounded-md border', 
    sm: 'w-16 aspect-[5/7] text-[0.625rem] rounded-md border-2',
    md: 'w-20 aspect-[5/7] text-xs rounded-lg border-2',
    lg: 'w-64 aspect-[5/7] text-lg rounded-2xl border-4', 
  };
  const currentSizeClass = sizeClasses[size];

  if (hidden) {
      return (
        <div 
            className={`${currentSizeClass} bg-indigo-900 border-indigo-400 shadow-md flex items-center justify-center relative touch-none`}
        >
            <div className="w-1/3 h-1/3 rounded-full bg-indigo-500 animate-pulse"></div>
        </div>
      )
  }

  // Border Color based on Ability Tag
  let borderColor = 'border-gray-600';
  if (def.tags.includes('OnReveal')) borderColor = 'border-yellow-500';
  else if (def.tags.includes('Ongoing')) borderColor = 'border-blue-500';
  else if (def.tags.includes('Destroy')) borderColor = 'border-red-500';
  else if (def.tags.includes('Move')) borderColor = 'border-purple-500';

  // Stats Logic
  const basePower = def.basePower;
  const currentDisplayPower = isInstance(card) ? card.totalPower : basePower;

  const baseCost = def.baseCost;
  const currentDisplayCost = isInstance(card) ? card.totalCost : baseCost;

  const powerColor = currentDisplayPower > basePower ? 'text-green-400' : (currentDisplayPower < basePower ? 'text-red-400' : 'text-white');
  const costColor = currentDisplayCost < baseCost ? 'text-green-400' : (currentDisplayCost > baseCost ? 'text-red-400' : 'text-white');

  const opacityClass = isDragging ? 'opacity-50' : 'opacity-100';
  const cursorClass = onPointerDown || onClick ? 'cursor-grab active:cursor-grabbing' : '';
  const borderClass = size === 'xs' ? 'border' : (size === 'lg' ? 'border-4' : 'border-2');

  // VIEW SELECTION

  if (variant === 'board') {
    return (
        <CardBoardView 
            def={def}
            borderColor={borderColor}
            borderClass={borderClass}
            opacityClass={opacityClass}
            cursorClass={cursorClass}
            size={size}
            currentDisplayCost={currentDisplayCost}
            currentDisplayPower={currentDisplayPower}
            costColor={costColor}
            powerColor={powerColor}
            onPointerDown={onPointerDown}
            onClick={onClick}
        />
    );
  }

  if (size === 'lg') {
      return (
        <CardFullArtView 
            def={def}
            currentSizeClass={currentSizeClass}
            borderColor={borderColor}
            opacityClass={opacityClass}
            size={size}
            currentDisplayCost={currentDisplayCost}
            currentDisplayPower={currentDisplayPower}
            costColor={costColor}
            powerColor={powerColor}
        />
      );
  }

  return (
    <CardStandardView 
        def={def}
        currentSizeClass={currentSizeClass}
        borderColor={borderColor}
        opacityClass={opacityClass}
        cursorClass={cursorClass}
        size={size}
        currentDisplayCost={currentDisplayCost}
        currentDisplayPower={currentDisplayPower}
        costColor={costColor}
        powerColor={powerColor}
        onPointerDown={onPointerDown}
        onClick={onClick}
    />
  );
};

