export const InspectorOverlay: React.FC = () => {
    const { inspectingCard, inspectingLocation, actions } = useGame();

    if (!inspectingCard && !inspectingLocation) return null;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;
    const isInstanceWithStats = (c: any): c is CardInstance => c && 'costModifiers' in c && 'powerModifiers' in c;

    const getCardText = () => {
        if (!inspectingCard) return '';
        const def = isInstance(inspectingCard) ? inspectingCard.def : inspectingCard;
        return isInstance(inspectingCard) ? inspectingCard.currentText : def.baseText;
    };

    return (
        <div 
            className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-pop overflow-y-auto touch-none"
            onClick={actions.closeInspector}
        >
            {/* Card Inspector Content */}
            {inspectingCard && (
                <div className="flex flex-col items-center w-full max-w-[20rem] mt-12"> 

                    <div className="relative z-40 scale-110 mb-6 shadow-[0_0_50px_rgba(0,0,0,0.5)]">

                        {/* STATS HISTORY OVERLAYS */}
                        {isInstanceWithStats(inspectingCard) && (
                            <>
                                <StatHistory modifiers={inspectingCard.costModifiers} type="cost" side="left" />
                                <StatHistory modifiers={inspectingCard.powerModifiers} type="power" side="right" />
                            </>
                        )}

                        <Card card={inspectingCard} size="lg" />
                    </div>

                    {/* Bottom: Description Text Only */}
                    <div className="w-full max-w-xs text-center leading-relaxed animate-slide-up px-2 select-text">
                         <KeywordText text={getCardText()} />
                    </div>
                </div>
            )}

            {/* Location Inspector Content */}
            {inspectingLocation && (
                <div className="relative z-40 scale-125 animate-pop drop-shadow-2xl">
                    <LocationCard location={inspectingLocation} size="lg" />
                </div>
            )}

            <div className="fixed bottom-8 text-white/30 text-xs tracking-[0.2em] uppercase font-bold animate-pulse pointer-events-none">
                Tap background to close
            </div>

            <style>{`
                @keyframes slide-up {
                    from { opacity: 0; transform: translateY(10px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                .animate-slide-up {
                    animation: slide-up 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </div>
    );
};

