import React, { createContext, useContext, useState, ReactNode } from 'react';
import { UserProfile } from '../types';
import { audio } from '../services/audio';

interface UserContextType {
    user: UserProfile;
    addCredits: (amount: number) => void;
    spendCredits: (amount: number) => boolean;
    addGold: (amount: number) => void;
    spendGold: (amount: number) => boolean;
    setActiveDeck: (id: number) => void;
}

// Initial Mock Data
const INITIAL_USER: UserProfile = {
    id: 'u1',
    username: 'Commander',
    level: 42,
    credits: 1250,
    gold: 500,
    activeDeckId: 1,
    avatarId: 'avatar_01'
};

const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<UserProfile>(INITIAL_USER);

    const addCredits = (amount: number) => {
        setUser(prev => ({ ...prev, credits: prev.credits + amount }));
        audio.play('sfx_ui_click'); // Reuse click for sound feedback
    };

    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) {
            setUser(prev => ({ ...prev, credits: prev.credits - amount }));
            return true;
        }
        return false;
    };

    const addGold = (amount: number) => {
        setUser(prev => ({ ...prev, gold: prev.gold + amount }));
        audio.play('sfx_ui_click');
    };

    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) {
            setUser(prev => ({ ...prev, gold: prev.gold - amount }));
            return true;
        }
        return false;
    };

    const setActiveDeck = (id: number) => {
        setUser(prev => ({ ...prev, activeDeckId: id }));
    };

    return (
        <UserContext.Provider value={{ user, addCredits, spendCredits, addGold, spendGold, setActiveDeck }}>
            {children}
        </UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) {
        throw new Error('useUser must be used within a UserProvider');
    }
    return context;
};

import React, { useState, useEffect } from 'react';
import { AppShell } from './components/ui/AppShell';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  // --- Auth & Init State ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  // --- Navigation Logic (Extracted) ---
  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // --- App Initialization ---
  useEffect(() => {
    const initApp = async () => {
      await preloadAssets((progress) => setLoadingProgress(progress));
      setTimeout(() => setIsLoading(false), 500);
    };
    initApp();
  }, []);

  // --- Handlers ---
  const handleLogin = () => {
      audio.playUiClick();
      setIsLoggedIn(true);
  };

  const handleLogout = () => {
      audio.playUiClick();
      setIsLoggedIn(false);
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  // --- Render Flow ---

  // 1. Auth Gate
  if (!isLoggedIn) {
      return (
          <AppShell>
              <LoginScreen onLogin={handleLogin} />
          </AppShell>
      );
  }

  // 2. Main Application
  return (
    <UserProvider>
        <AppShell>
        {/* Global Loading Overlay */}
        <div 
            className={`absolute inset-0 z-[100] transition-opacity duration-700 pointer-events-none ${isLoading ? 'opacity-100 pointer-events-auto' : 'opacity-0'}`}
        >
            {isLoading && <LoadingScreen progress={loadingProgress} />}
        </div>

        {/* The World Container (Infinite Canvas) */}
        <div 
            className="w-full h-full relative transition-transform duration-700 ease-[cubic-bezier(0.25,1,0.5,1)] will-change-transform"
            style={containerStyle}
        >
            {/* Screen Renderer */}
            {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
                // Culling Logic
                const shouldRender = key === activeScreen || (isTransitioning && key === prevScreen);

                if (!shouldRender) return null;

                const config = WORLDS[key];
                const ScreenComponent = config.component;

                return (
                    <div 
                        key={key}
                        className="absolute w-full h-full top-0 left-0 overflow-hidden"
                        style={{ 
                            transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)` 
                        }}
                    >
                        <ScreenComponent 
                            onNavigate={navigateTo} 
                            onExit={() => navigateTo('MENU')}
                            onBack={() => navigateTo('MENU')}
                            onStartGame={handleStartGame}
                            onLogout={handleLogout}
                        />
                    </div>
                );
            })}
        </div>

        {/* Global Navigation Bar (Hidden in Game) */}
        {activeScreen !== 'GAME' && !isLoading && (
            <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} />
        )}

        </AppShell>
    </UserProvider>
  );
}

