import { CardDefinition, CardInstance } from '../types';

export const getCardBorderColor = (tags: string[]): string => {
    if (tags.includes('OnReveal')) return 'border-yellow-500';
    if (tags.includes('Ongoing')) return 'border-blue-500';
    if (tags.includes('Destroy')) return 'border-red-500';
    if (tags.includes('Move')) return 'border-purple-500';
    if (tags.includes('Discard')) return 'border-slate-400';
    if (tags.includes('Summon')) return 'border-emerald-500';
    return 'border-gray-600';
};

export const getCardStats = (card: CardInstance | CardDefinition) => {
    const isInstance = (c: any): c is CardInstance => 'instanceId' in c;
    const def = isInstance(card) ? card.def : card;

    const basePower = def.basePower;
    const currentDisplayPower = isInstance(card) ? card.totalPower : basePower;

    const baseCost = def.baseCost;
    const currentDisplayCost = isInstance(card) ? card.totalCost : baseCost;

    const powerColor = currentDisplayPower > basePower 
        ? 'text-green-400' 
        : (currentDisplayPower < basePower ? 'text-red-400' : 'text-white');

    const costColor = currentDisplayCost < baseCost 
        ? 'text-green-400' 
        : (currentDisplayCost > baseCost ? 'text-red-400' : 'text-white');

    return {
        basePower,
        currentDisplayPower,
        baseCost,
        currentDisplayCost,
        powerColor,
        costColor,
        def
    };
};

