// Optimization: Memoize Card to prevent re-renders on unrelated state changes
export const Card = React.memo(CardComponent, (prev, next) => {
    // 1. Check simple primitives
    if (prev.size !== next.size) return false;
    if (prev.variant !== next.variant) return false;
    if (prev.hidden !== next.hidden) return false;
    if (prev.isDragging !== next.isDragging) return false;
    if (prev.isSelected !== next.isSelected) return false;
    if (prev.isPlayable !== next.isPlayable) return false;

    // 2. Check Card Data Integrity
    const prevId = 'instanceId' in prev.card ? prev.card.instanceId : prev.card.id;
    const nextId = 'instanceId' in next.card ? next.card.instanceId : next.card.id;
    if (prevId !== nextId) return false;

    // 3. Deep Check Stats (Cost/Power)
    // If it's an instance, we need to check if stats changed
    if ('instanceId' in prev.card && 'instanceId' in next.card) {
        if (prev.card.totalPower !== next.card.totalPower) return false;
        if (prev.card.totalCost !== next.card.totalCost) return false;
        if (prev.card.zone !== next.card.zone) return false;
        if (prev.card.faceUp !== next.card.faceUp) return false;
    }

    return true; 
});

