import { GoogleGenAI, Type } from "@google/genai";
import { GameState, CardDefinition } from "../types";
import { PendingMove } from "./planning";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const gemini = {
    /**
     * Decisions smarter moves for the AI opponent.
     */
    async getSmartMoves(gameState: GameState): Promise<PendingMove[]> {
        const prompt = `
            You are an elite tactical AI for a 3-lane card game similar to Marvel Snap.
            Goal: Win 2 out of 3 lanes.
            Lanes: 0, 1, 2.

            Current Game State:
            ${JSON.stringify(gameState, null, 2)}

            Rules:
            1. You can only play cards from your hand (p2).
            2. Total cost must be <= energy.
            3. Each lane has max 4 slots.

            Respond ONLY with a JSON array of moves: [{"cardInstanceId": "string", "laneIdx": number}].
        `;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            cardInstanceId: { type: Type.STRING },
                            laneIdx: { type: Type.NUMBER }
                        },
                        required: ["cardInstanceId", "laneIdx"]
                    }
                }
            }
        });

        try {
            return JSON.parse(response.text);
        } catch (e) {
            console.error("Gemini Move Parsing Error", e);
            return [];
        }
    },

    /**
     * Generates a 2-sentence backstory for a card.
     */
    async generateLore(card: CardDefinition): Promise<string> {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: `Write a gritty 2-sentence sci-fi backstory for a card named "${card.name}" with the ability: "${card.baseText}". Do not use quotes.`
        });
        return response.text || "Records redacted by High Command.";
    },

    /**
     * Generates custom sci-fi art for a card.
     */
    async generateArt(card: CardDefinition): Promise<string | null> {
        const prompt = `Cinematic sci-fi character portrait for a card game. Character: ${card.name}. Context: ${card.baseText}. Style: Digital oil painting, dramatic lighting, galactic neon palette, high detail.`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: prompt }] }
        });

        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            }
        }
        return null;
    }
};

import { GameState } from '../types';
import { PendingMove } from './planning';
import { generateAiMoves } from './ai';
import { gemini } from './gemini';

export const api = {
    async submitTurn(gameState: GameState, playerMoves: PendingMove[]): Promise<{ opponentMoves: PendingMove[] }> {
        // We use a blend of local AI and Gemini Smart AI
        // In a real production app, we might check a user setting or turn number
        try {
            // Smart AI for middle and late game
            if (gameState.turn >= 2) {
                const smartMoves = await gemini.getSmartMoves(gameState);
                if (smartMoves && smartMoves.length > 0) {
                    return { opponentMoves: smartMoves };
                }
            }
        } catch (e) {
            console.warn("Smart AI failed, falling back to heuristic", e);
        }

        // Heuristic fallback
        const opponentMoves = generateAiMoves(gameState);
        return { opponentMoves };
    }
};

