import { Card } from './Card';
import { LocationCard } from './LocationCard';
import { StatHistory } from './inspector/StatHistory';
import { KeywordText } from './ui/KeywordText';

export const InspectorOverlay: React.FC = () => {
    const { 
        inspectingCard, 
        inspectingLocation, 
        inspectingCurrency,
        closeInspector 
    } = useUser();

    if (!inspectingCard && !inspectingLocation && !inspectingCurrency) return null;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;

    const getDef = (): CardDefinition | null => {
        if (!inspectingCard) return null;
        return isInstance(inspectingCard) ? inspectingCard.def : inspectingCard as CardDefinition;
    };

    const def = getDef();

    return (
        <div 
            className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-lg flex flex-col items-center justify-center p-6 animate-pop overflow-y-auto"
            onClick={closeInspector}
        >
            {/* CARD INSPECTOR */}
            {inspectingCard && def && (
                <div className="flex flex-col items-center w-full max-w-[20rem] mt-4"> 
                    <div className="relative z-40 scale-110 mb-8 shadow-[0_0_60px_rgba(0,0,0,0.8)]">
                        {isInstance(inspectingCard) && (
                            <>
                                <StatHistory modifiers={inspectingCard.costModifiers} type="cost" side="left" />
                                <StatHistory modifiers={inspectingCard.powerModifiers} type="power" side="right" />
                            </>
                        )}
                        <Card card={inspectingCard} size="lg" />
                    </div>

                    <div className="w-full text-center mb-6">
                         <KeywordText text={isInstance(inspectingCard) ? inspectingCard.currentText : def.baseText} />
                    </div>

                    {def.flavorText && (
                        <div className="w-full bg-slate-900/50 border border-slate-800 rounded-xl p-4 min-h-[4rem] flex flex-col items-center justify-center relative group overflow-hidden">
                            <p className="text-[0.7rem] text-indigo-200 italic leading-relaxed font-mono text-center">
                                "{def.flavorText}"
                            </p>
                        </div>
                    )}
                </div>
            )}

            {/* LOCATION INSPECTOR */}
            {inspectingLocation && (
                <div className="relative z-40 scale-125 animate-pop drop-shadow-2xl">
                    <LocationCard location={inspectingLocation} size="lg" />
                </div>
            )}

            {/* CURRENCY INSPECTOR */}
            {inspectingCurrency && (
                <div className="flex flex-col items-center animate-pop">
                    <div className={`w-32 h-32 rounded-full flex items-center justify-center border-4 shadow-[0_0_50px_rgba(255,255,255,0.1)] mb-6 ${inspectingCurrency.type === 'gold' ? 'bg-amber-500/20 border-amber-400' : 'bg-blue-500/20 border-blue-400'}`}>
