                        {inspectingCurrency.amount.toLocaleString()} {inspectingCurrency.type.toUpperCase()}
                    </h2>
                    <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">
                        Currency Deposit
                    </p>
                </div>
            )}

            <div className="fixed bottom-8 text-white/20 text-[0.6rem] tracking-[0.3em] uppercase font-black animate-pulse pointer-events-none">
                Close View
            </div>
        </div>
    );
