export const api = {
    async submitTurn(gameState: GameState, playerMoves: PendingMove[]): Promise<{ opponentMoves: PendingMove[] }> {
        const latency = 400 + Math.random() * 400;
        await new Promise(resolve => setTimeout(resolve, latency));
        const opponentMoves = generateAiMoves(gameState);
        return { opponentMoves };
    },

    /**
     * Authoritative offer list.
     * Logic: Server-side check for purchase eligibility.
     */
    async getStoreOffers(user: UserProfile): Promise<StoreOffer[]> {
        await new Promise(resolve => setTimeout(resolve, 600)); 

        return MOCK_STORE_OFFERS.filter(offer => {
            // 1. One-time check
            if (offer.isOneTime && user.purchasedOfferIds.includes(offer.id)) return false;

            // 2. Limit check
            if (offer.purchaseLimit) {
                const count = user.purchasedOfferIds.filter(id => id === offer.id).length;
                if (count >= offer.purchaseLimit) return false;
            }

            // 3. Expiry check
            if (offer.expiryDate && new Date(offer.expiryDate) < new Date()) return false;

            return true;
        });
    },

    /**
     * Authoritative purchase logic.
     * Mimics a transactional backend update.
     */
    async purchaseOffer(user: UserProfile, offerId: string): Promise<PurchaseResponse> {
        await new Promise(resolve => setTimeout(resolve, 1000));

        const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
        if (!offer) return { success: false, error: 'OFFER_EXPIRED_OR_NOT_FOUND' };

        // 1. Balance Validation (Server-Authoritative)
        if (offer.priceType === 'gold') {
            if (user.gold < (offer.priceAmount || 0)) {
                return { success: false, error: 'INSUFFICIENT_GOLD' };
            }
        }
        if (offer.priceType === 'credits') {
            if (user.credits < (offer.priceAmount || 0)) {
                return { success: false, error: 'INSUFFICIENT_CREDITS' };
            }
        }

        // 2. Ownership Validation
        // If a bundle contains a card the user already has, a real server might 
        // return a different response or alternative currency.
        const duplicates = offer.contents.filter(item => 
            item.type === 'card' && user.collection.includes(item.definitionId)
        );

        // Simulating a "Smart Pro-rating" or duplicate handling logic
        // For this demo, we just allow it but a real server would handle this.

        // 3. Success Response
        // Note: In a real app, the server returns the NEW state, not the diff.
        let newGold = user.gold;
        let newCredits = user.credits;

        if (offer.priceType === 'gold') newGold -= (offer.priceAmount || 0);
        if (offer.priceType === 'credits') newCredits -= (offer.priceAmount || 0);

        offer.contents.forEach(item => {
            if (item.type === 'currency') {
                if (item.currencyType === 'gold') newGold += item.amount;
                if (item.currencyType === 'credits') newCredits += item.amount;
            }
        });

        return { 
            success: true, 
            newBalances: { gold: newGold, credits: newCredits },
            addedItems: offer.contents.filter(i => i.type === 'card').map(i => (i as any).definitionId)
        };
    }
};

import React, { createContext, useContext, useState, ReactNode } from 'react';
import { UserProfile, OfferItem, CardDefinition, CardInstance, LocationDefinition } from '../types';
import { audio } from '../services/audio';
import { api } from '../services/api';
import { CARDS } from '../constants';

interface UserContextType {
    user: UserProfile;
    // Inspect State
    inspectingCard: CardInstance | CardDefinition | null;
    inspectingLocation: LocationDefinition | null;
    inspectingCurrency: { type: 'gold' | 'credits', amount: number } | null;
    // Actions
    addCredits: (amount: number) => void;
    spendCredits: (amount: number) => boolean;
    addGold: (amount: number) => void;
    spendGold: (amount: number) => boolean;
    setActiveDeck: (id: number) => void;
    processPurchase: (offerId: string) => Promise<boolean>;
    // Inspector Methods
    inspect: (item: CardInstance | CardDefinition | LocationDefinition | { type: 'gold' | 'credits', amount: number }) => void;
    closeInspector: () => void;
}

const INITIAL_USER: UserProfile = {
    id: 'u1',
    username: 'Commander',
    level: 42,
    credits: 1250,
    gold: 500,
    activeDeckId: 1,
    avatarId: 'avatar_01',
    purchasedOfferIds: [],
    collection: CARDS.map(c => c.id).slice(0, 12)
};

const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<UserProfile>(INITIAL_USER);

    // Global Inspector State
    const [inspectingCard, setInspectingCard] = useState<CardInstance | CardDefinition | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);

    const inspect = (item: any) => {
        audio.playUiClick();
        if ('type' in item && (item.type === 'gold' || item.type === 'credits')) {
            setInspectingCurrency(item);
            setInspectingCard(null);
            setInspectingLocation(null);
        } else if ('effect' in item && 'baseText' in item) {
            setInspectingCard(item);
            setInspectingLocation(null);
            setInspectingCurrency(null);
        } else if ('description' in item) {
            setInspectingLocation(item);
            setInspectingCard(null);
            setInspectingCurrency(null);
        }
    };

    const closeInspector = () => {
        setInspectingCard(null);
        setInspectingLocation(null);
        setInspectingCurrency(null);
    };

    const addCredits = (amount: number) => {
        setUser(prev => ({ ...prev, credits: prev.credits + amount }));
    };

    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) {
            setUser(prev => ({ ...prev, credits: prev.credits - amount }));
            return true;
        }
        return false;
    };

    const addGold = (amount: number) => {
        setUser(prev => ({ ...prev, gold: prev.gold + amount }));
    };

    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) {
            setUser(prev => ({ ...prev, gold: prev.gold - amount }));
            return true;
        }
        return false;
    };

    const setActiveDeck = (id: number) => {
        setUser(prev => ({ ...prev, activeDeckId: id }));
    };

    /**
     * Transactional Purchase Flow.
     * Instead of local math, we send the user context to the server mock
     * and apply the official response.
     */
    const processPurchase = async (offerId: string): Promise<boolean> => {
        const response = await api.purchaseOffer(user, offerId);

        if (response.success && response.newBalances) {
            audio.play('sfx_ui_click');

            setUser(prev => {
                const updatedUser = { ...prev };

                // 1. Apply Server-Calculated Balances
                updatedUser.gold = response.newBalances!.gold;
                updatedUser.credits = response.newBalances!.credits;

                // 2. Update Collection
                if (response.addedItems) {
                    const newCollection = new Set([...prev.collection, ...response.addedItems]);
                    updatedUser.collection = Array.from(newCollection);
                }

                // 3. Log purchase history
                updatedUser.purchasedOfferIds = [...prev.purchasedOfferIds, offerId];

                return updatedUser;
            });
            return true;
        } else {
            console.error("Purchase Error:", response.error);
            return false;
        }
    };

    return (
        <UserContext.Provider value={{ 
            user, 
            inspectingCard, 
            inspectingLocation, 
            inspectingCurrency,
            addCredits, 
            spendCredits, 
            addGold, 
            spendGold, 
            setActiveDeck, 
            processPurchase,
            inspect,
            closeInspector
        }}>
            {children}
        </UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) {
        throw new Error('useUser must be used within a UserProvider');
    }
    return context;
};

