export const api = {
    async submitTurn(gameState: GameState, playerMoves: PendingMove[]): Promise<{ opponentMoves: PendingMove[] }> {
        const latency = 400 + Math.random() * 400;
        await new Promise(resolve => setTimeout(resolve, latency));
        const opponentMoves = generateAiMoves(gameState);
        return { opponentMoves };
    },

    async getStoreOffers(user: UserProfile): Promise<StoreOffer[]> {
        await new Promise(resolve => setTimeout(resolve, 600)); 
        return MOCK_STORE_OFFERS.filter(offer => {
            if (offer.isOneTime && user.purchasedOfferIds.includes(offer.id)) return false;

            if (offer.purchaseLimit) {
                const count = user.purchasedOfferIds.filter(id => id === offer.id).length;
                if (count >= offer.purchaseLimit) return false;
            }

            if (offer.expiryDate && new Date(offer.expiryDate) < new Date()) return false;

            return true;
        }).map(offer => {
            // Computed field: availableAt
            if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
                const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
                const availableAt = new Date(lastClaimed + (offer.cooldownSeconds * 1000));
                return { ...offer, availableAt: availableAt.toISOString() };
            }
            return offer;
        });
    },

    /**
     * TRANSACTIONAL PURCHASE
     * - Checks for idempotency (nonce)
     * - Validates cooldowns
     * - Validates state (gold/credits)
     * - Returns FULL server-sync state
     */
    async purchaseOffer(user: UserProfile, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        // Network Latency Simulation
        await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400));

        // 1. Idempotency Check (Production safety)
        if (processedTransactions.has(transactionId)) {
            return { success: false, errorCode: 'ERR_DUPLICATE_TRANSACTION', transactionId };
        }

        const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
        if (!offer) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId };

        // 2. Cooldown Check
        if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
            const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
            const now = Date.now();
            if (now < lastClaimed + (offer.cooldownSeconds * 1000)) {
                return { success: false, errorCode: 'ERR_COOLDOWN_ACTIVE', transactionId };
            }
        }

        // 3. Authoritative Resource Check
        if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) {
            return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        }
        if (offer.priceType === 'credits' && user.credits < (offer.priceAmount || 0)) {
            return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        }

        // 4. Process Transaction (Atomic)
        processedTransactions.add(transactionId);

        const updatedProfile: UserProfile = { ...user };

        // Deduct Price
        if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
        if (offer.priceType === 'credits') updatedProfile.credits -= (offer.priceAmount || 0);

        // Add Items
        offer.contents.forEach(item => {
            if (item.type === 'currency') {
                if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
            } else if (item.type === 'card') {
                if (!updatedProfile.collection.includes(item.definitionId)) {
                    updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
                }
            }
        });

        // Update tracking
        updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];
        updatedProfile.lastClaimedDates = { ...updatedProfile.lastClaimedDates, [offerId]: new Date().toISOString() };

        return { 
            success: true, 
            transactionId, 
            updatedProfile 
        };
    }
};

