            setInspectingCard(null);
            setInspectingCurrency(null);
        }
    };

    const closeInspector = () => {
        setInspectingCard(null);
        setInspectingLocation(null);
        setInspectingCurrency(null);
    };

    const addCredits = (amount: number) => {
        setUser(prev => ({ ...prev, credits: prev.credits + amount }));
    };

    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) {
            setUser(prev => ({ ...prev, credits: prev.credits - amount }));
            return true;
        }
        return false;
    };

    const addGold = (amount: number) => {
        setUser(prev => ({ ...prev, gold: prev.gold + amount }));
    };

    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) {
            setUser(prev => ({ ...prev, gold: prev.gold - amount }));
            return true;
        }
        return false;
    };

    const setActiveDeck = (id: number) => {
        setUser(prev => ({ ...prev, activeDeckId: id }));
    };

    /**
     * Transactional Sync Flow
     */
    const processPurchase = async (offerId: string): Promise<boolean> => {
        // Create a unique nonce for this specific click
        const transactionId = `txn_${generateInstanceId()}`;

        try {
            const response = await api.purchaseOffer(user, offerId, transactionId);

            if (response.success && response.updatedProfile) {
                audio.play('sfx_victory');
                // AUTHORITY SYNC: We replace our state with the server's official state
                setUser(response.updatedProfile);
                return true;
            } else {
                console.warn(`Purchase failed [${response.errorCode}]`);
                audio.play('sfx_ui_hover');
                return false;
            }
        } catch (err) {
            console.error("Network Exception:", err);
            return false;
        }
    };

    return (
        <UserContext.Provider value={{ 
            user, 
            inspectingCard, 
            inspectingLocation, 
            inspectingCurrency,
            addCredits, 
            spendCredits, 
            addGold, 
            spendGold, 
            setActiveDeck, 
            processPurchase,
            inspect,
            closeInspector
        }}>
            {children}
        </UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) {
        throw new Error('useUser must be used within a UserProvider');
    }
    return context;
};

import React, { useState, useEffect } from 'react';
import { HexButton } from '../ui/HexButton';
import { useUser } from '../../contexts/UserContext';

interface StoreCreditItemProps {
    amount: number;
    cost: number | 'FREE';
    offerId?: string; // Optional for tracking specific offers
    availableAt?: string; // ISO string from server
}

export const StoreCreditItem: React.FC<StoreCreditItemProps> = ({ amount, cost, offerId, availableAt }) => {
    const { spendGold, addCredits, processPurchase } = useUser();
    const isFree = cost === 'FREE';

    // Timer logic
    const [timeLeft, setTimeLeft] = useState<number>(0);

    useEffect(() => {
        if (!availableAt) return;

        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handlePurchase = async () => {
        if (timeLeft > 0) return;

        if (isFree && offerId) {
            // Use the transactional purchase flow for tracked offers
            await processPurchase(offerId);
        } else if (isFree) {
            // Legacy/Hardcoded support
            addCredits(amount);
        } else {
            const success = spendGold(cost as number);
            if (success) {
                addCredits(amount);
            } else {
                alert("Not enough Gold!");
            }
        }
    };

    const formatTime = (seconds: number) => {
        if (seconds < 60) return `${seconds}s`;
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}m ${s}s`;
    };

    const GoldIcon = () => (
        <div className="w-2 h-1.5 rounded-[1px] bg-amber-400 shadow-[0_0_3px_rgba(251,191,36,0.8)] border border-amber-200"></div>
    );

    return (
        <div className="bg-slate-900/50 border border-slate-800 rounded-xl p-2 flex flex-col items-center justify-between gap-1 h-full relative group transition-colors hover:bg-slate-900/80">
            {isFree && timeLeft === 0 && (
                <div className="absolute -top-1 -left-1 z-30">
                     <div className="bg-emerald-600 text-white text-[0.45rem] font-black px-1.5 py-0.5 rounded shadow-lg uppercase tracking-wider animate-pulse">
                        READY
                     </div>
                </div>
            )}

            <div className="mt-1 font-black text-white text-sm leading-none text-center drop-shadow-md italic">
                {amount}
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-2 min-h-[3.5rem]">
                <div className="w-10 h-10 rounded-full bg-blue-500/10 flex items-center justify-center border border-blue-500/30 shadow-[0_0_10px_rgba(59,130,246,0.2)]">
                    <div className="w-7 h-7 rounded-sm bg-gradient-to-tr from-blue-600 to-blue-400 shadow-lg border border-blue-300 transform rotate-45"></div>
                </div>
            </div>

            <div className="w-full mt-auto">
                {timeLeft > 0 ? (
                    <div className="h-8 w-full bg-slate-950/50 border border-slate-700/50 rounded-lg flex items-center justify-center gap-1.5 overflow-hidden group-hover:bg-red-950/20 transition-colors">
                        <svg className="w-2.5 h-2.5 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-tighter tabular-nums">
                            {formatTime(timeLeft)}
                        </span>
                    </div>
                ) : (
                    <HexButton 
                        variant={isFree ? 'success' : 'secondary'} 
                        size="sm" 
                        fullWidth
                        className="!text-[0.6rem]"
                        onClick={handlePurchase}
                    >
                        {isFree ? "FREE" : <div className="flex items-center justify-center gap-1"><GoldIcon /> {cost}</div>}
                    </HexButton>
                )}
            </div>
        </div>
    );
};

