const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<UserProfile>(INITIAL_USER);

    // Global Store State
    const [storeData, setStoreData] = useState<StoreData | null>(null);
    const [isStoreLoading, setIsStoreLoading] = useState(false);

    // Global Inspector State
    const [inspectingCard, setInspectingCard] = useState<CardInstance | CardDefinition | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);

    // --- Actions ---

    const syncStore = useCallback(async (showLoading = false) => {
        if (showLoading) setIsStoreLoading(true);
        try {
            const data = await api.getStoreOffers(user);
            setStoreData(data);
        } catch (e) {
            console.error("Store Sync Failed", e);
        } finally {
            setIsStoreLoading(false);
        }
    }, [user]);

    // Initial Fetch & Background Polling
    useEffect(() => {
        // Initial fetch
        syncStore(true);

        // Polling logic
        let timeout: ReturnType<typeof setTimeout>;
        const poll = () => {
            const delay = (storeData?.refreshHintSeconds || 60) * 1000;
            timeout = setTimeout(async () => {
                await syncStore();
                poll();
            }, delay);
        };

        poll();
        return () => clearTimeout(timeout);
    }, [user.id]); // Only reset poll if user changes

    // Re-sync immediately on purchase to hide one-time offers or update limits
    useEffect(() => {
        if (user.purchasedOfferIds.length > 0) {
            syncStore();
        }
    }, [user.purchasedOfferIds.length]);

    const inspect = (item: any) => {
        audio.playUiClick();
        if ('type' in item && (item.type === 'gold' || item.type === 'credits')) {
            setInspectingCurrency(item);
            setInspectingCard(null);
            setInspectingLocation(null);
        } else if ('effect' in item && 'baseText' in item) {
            setInspectingCard(item);
            setInspectingLocation(null);
            setInspectingCurrency(null);
        } else if ('description' in item) {
            setInspectingLocation(item);
            setInspectingCard(null);
            setInspectingCurrency(null);
        }
    };

    const closeInspector = () => {
        setInspectingCard(null);
        setInspectingLocation(null);
        setInspectingCurrency(null);
    };

    const addCredits = (amount: number) => {
        setUser(prev => ({ ...prev, credits: prev.credits + amount }));
    };

    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) {
            setUser(prev => ({ ...prev, credits: prev.credits - amount }));
            return true;
        }
        return false;
    };

    const addGold = (amount: number) => {
        setUser(prev => ({ ...prev, gold: prev.gold + amount }));
    };

    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) {
            setUser(prev => ({ ...prev, gold: prev.gold - amount }));
            return true;
        }
        return false;
    };

    const setActiveDeck = (id: number) => {
        setUser(prev => ({ ...prev, activeDeckId: id }));
    };

    const processPurchase = async (offerId: string): Promise<boolean> => {
        const transactionId = `txn_${generateInstanceId()}`;

        try {
            const response = await api.purchaseOffer(user, offerId, transactionId);

            if (response.success && response.updatedProfile) {
                audio.play('sfx_victory');
                setUser(response.updatedProfile);
                return true;
            } else {
                console.warn(`Purchase failed [${response.errorCode}]`);
                audio.play('sfx_ui_hover');
                return false;
            }
        } catch (err) {
            console.error("Network Exception:", err);
            return false;
        }
    };

    return (
        <UserContext.Provider value={{ 
            user, 
            storeData,
            isStoreLoading,
            inspectingCard, 
            inspectingLocation, 
            inspectingCurrency,
            addCredits, 
            spendCredits, 
            addGold, 
            spendGold, 
            setActiveDeck, 
            processPurchase,
            syncStore,
            inspect,
            closeInspector
        }}>
            {children}
        </UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) {
        throw new Error('useUser must be used within a UserProvider');
    }
    return context;
};

