import React, { useState, useRef, useEffect } from 'react';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: variant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    holdDuration?: number; // Duration in ms to hold before triggering
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    className = '',
    holdDuration = 0,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.25rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.25rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.25rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.25rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.25rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.25rem_0_rgb(30,58,138)]",
    };

    const sizes = {
        sm: "h-8 text-[0.8rem]",
        md: "h-10 text-[1rem]",
        lg: "h-14 text-[1.25rem]"
    };

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                // Trigger action
                if (onClick) {
                    const syntheticEvent = { ...e, type: 'click' } as unknown as React.MouseEvent<HTMLButtonElement>;
                    onClick(syntheticEvent);
                }
                // Reset after successful hold
                setIsHolding(false);
                setProgress(0);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        setProgress(0);
    };

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthClass = fullWidth ? 'w-full' : '';

    return (
        <div className={`relative group ${widthClass} ${sizes[size]} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                {...props}
            >
                {/* Background Shape */}
                <div className={`
                    absolute inset-0 bg-gradient-to-b border-2 rounded-lg skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {/* Progress Bar Layer */}
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                {/* Content */}
                <div className="absolute inset-0 flex items-center justify-center z-20 skew-x-[-10deg] px-1 pointer-events-none">
                    <span className="font-black text-white italic tracking-tighter uppercase drop-shadow-md flex items-center gap-1.5 whitespace-nowrap">
                        {isHolding ? (
                            <span className="animate-pulse">HOLD...</span>
                        ) : (
                            children
                        )}
                    </span>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { HexButton } from '../ui/HexButton';
import { useUser } from '../../contexts/UserContext';

interface StoreCreditItemProps {
    amount: number;
    cost: number | 'FREE';
    offerId?: string; // Optional for tracking specific offers
    availableAt?: string; // ISO string from server
}

export const StoreCreditItem: React.FC<StoreCreditItemProps> = ({ amount, cost, offerId, availableAt }) => {
    const { spendGold, addCredits, processPurchase } = useUser();
    const isFree = cost === 'FREE';

    // Timer logic
    const [timeLeft, setTimeLeft] = useState<number>(0);

    useEffect(() => {
        if (!availableAt) return;

        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handlePurchase = async () => {
        if (timeLeft > 0) return;

        if (isFree && offerId) {
            // Use the transactional purchase flow for tracked offers
            await processPurchase(offerId);
        } else if (isFree) {
            // Legacy/Hardcoded support
            addCredits(amount);
        } else {
            const success = spendGold(cost as number);
            if (success) {
                addCredits(amount);
            } else {
                alert("Not enough Gold!");
            }
        }
    };

    const formatTime = (seconds: number) => {
        if (seconds < 60) return `${seconds}s`;
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}m ${s}s`;
    };

    const GoldIcon = () => (
        <div className="w-2 h-1.5 rounded-[1px] bg-amber-400 shadow-[0_0_0.1875rem_rgba(251,191,36,0.8)] border border-amber-200"></div>
    );

    return (
        <div className="bg-slate-900/50 border border-slate-800 rounded-xl p-2 flex flex-col items-center justify-between gap-1 h-full relative group transition-colors hover:bg-slate-900/80">
            {isFree && timeLeft === 0 && (
                <div className="absolute -top-1 -left-1 z-30">
                     <div className="bg-emerald-600 text-white text-[0.45rem] font-black px-1.5 py-0.5 rounded shadow-lg uppercase tracking-wider animate-pulse">
                        READY
                     </div>
                </div>
            )}

            <div className="mt-1 font-black text-white text-sm leading-none text-center drop-shadow-md italic">
                {amount}
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-2 min-h-[3.5rem]">
                <div className="w-10 h-10 rounded-full bg-blue-500/10 flex items-center justify-center border border-blue-500/30 shadow-[0_0_0.625rem_rgba(59,130,246,0.2)]">
                    <div className="w-7 h-7 rounded-sm bg-gradient-to-tr from-blue-600 to-blue-400 shadow-lg border border-blue-300 transform rotate-45"></div>
                </div>
            </div>

            <div className="w-full mt-auto">
                {timeLeft > 0 ? (
                    <div className="h-8 w-full bg-slate-950/50 border border-slate-700/50 rounded-lg flex items-center justify-center gap-1.5 overflow-hidden group-hover:bg-red-950/20 transition-colors">
                        <svg className="w-2.5 h-2.5 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-tighter tabular-nums">
                            {formatTime(timeLeft)}
                        </span>
                    </div>
                ) : (
                    <HexButton 
                        variant={isFree ? 'success' : 'secondary'} 
                        size="sm" 
                        fullWidth
                        onClick={handlePurchase}
                        holdDuration={isFree ? 0 : 5000}
                    >
                        {isFree ? "FREE" : <div className="flex items-center justify-center gap-1"><GoldIcon /> {cost}</div>}
                    </HexButton>
                )}
            </div>
        </div>
    );
};

