                            {isPurchasing ? 'SYNCING...' : `PURCHASE - ${offer.price}`}
                        </HexButton>
                    </div>
                    <p className="mt-6 text-[0.6rem] text-slate-500 font-bold text-center uppercase tracking-[0.2em] leading-relaxed">
                        Cards added to collection instantly.<br/>Authoritative transaction via Galactic Proxy.
                    </p>
