import React, { useState, useEffect } from 'react';
import { HexButton } from '../ui/HexButton';
import { useUser } from '../../contexts/UserContext';
import { audio } from '../../services/audio';

interface StoreCreditItemProps {
    amount: number;
    cost: number | 'FREE';
    offerId?: string; 
    availableAt?: string; 
}

export const StoreCreditItem: React.FC<StoreCreditItemProps> = ({ amount, cost, offerId, availableAt }) => {
    const { spendGold, addCredits, processPurchase } = useUser();
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');
    const isFree = cost === 'FREE';

    const [timeLeft, setTimeLeft] = useState<number>(0);

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handlePurchase = async () => {
        if (timeLeft > 0 || status !== 'idle') return;

        setStatus('processing');

        let success = false;
        if (isFree && offerId) {
            success = await processPurchase(offerId);
        } else if (isFree) {
            addCredits(amount);
            success = true;
        } else {
            const hasFunds = spendGold(cost as number);
            if (hasFunds) {
                addCredits(amount);
                success = true;
            } else {
                alert("Not enough Gold!");
                setStatus('idle');
                return;
            }
        }

        if (success) {
            // Simulated network "sync" delay for visual consistency
            setTimeout(() => {
                setStatus('success');
                audio.play('sfx_victory', 0.5);
                setTimeout(() => setStatus('idle'), 2000);
            }, 600);
        } else {
            setStatus('idle');
        }
    };

    const formatTime = (seconds: number) => {
        if (seconds < 60) return `${seconds}s`;
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}m ${s}s`;
    };

    const GoldIcon = () => (
        <div className="w-2 h-1.5 rounded-[1px] bg-amber-400 shadow-[0_0_0.1875rem_rgba(251,191,36,0.8)] border border-amber-200"></div>
    );

    return (
        <div className={`bg-black border border-slate-700 rounded-xl p-2 flex flex-col items-center justify-between gap-1 h-full relative group transition-all duration-300 shadow-2xl overflow-hidden ${status === 'success' ? 'ring-2 ring-emerald-500 bg-emerald-950' : ''}`}>
            {/* Purchase Success Flash */}
            {status === 'success' && (
                <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />
            )}

            {/* Obnoxiously Bright Hold Progress Background */}
            {holdProgress > 0 && status === 'idle' && (
                <div 
                    className="absolute inset-y-0 left-0 bg-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.8)] z-0 transition-all duration-75 ease-linear"
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {isFree && timeLeft === 0 && status === 'idle' && (
                <div className="absolute -top-1 -left-1 z-30">
                     <div className="bg-emerald-600 text-white text-[0.45rem] font-black px-1.5 py-0.5 rounded shadow-lg uppercase tracking-wider">
                        READY
                     </div>
                </div>
            )}

            <div className="mt-1 font-black text-white text-sm leading-none text-center drop-shadow-md italic relative z-10">
                {amount}
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-2 min-h-[3.5rem] relative z-10">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center border transition-all duration-500 ${status === 'success' ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.5)]' : 'bg-blue-900 border-blue-500/50'}`}>
                    {status === 'success' ? (
                        <svg className="w-6 h-6 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        <div className="w-7 h-7 rounded-sm bg-gradient-to-tr from-blue-600 to-blue-400 shadow-lg border border-blue-300 transform rotate-45"></div>
                    )}
                </div>
            </div>

            {/* Hold Feedback Area - Adjusted height and alignment */}
            <div className="w-full h-3 relative flex items-center justify-center pointer-events-none mb-1 z-10 overflow-visible">
                {isHolding && status === 'idle' && (
                    <div className="relative font-black text-[0.55rem] uppercase tracking-widest leading-none drop-shadow-sm">
                        <span className="text-white/40 whitespace-nowrap">HOLD TO BUY</span>
                        <div 
                            className="absolute inset-0 text-white whitespace-nowrap overflow-hidden transition-all duration-75 ease-linear"
                            style={{ width: `${holdProgress}%` }}
                        >
                            HOLD TO BUY
                        </div>
                    </div>
                )}
                {status === 'processing' && (
                    <span className="text-[0.55rem] font-black text-blue-400 uppercase tracking-widest leading-none animate-pulse">SYNCING...</span>
                )}
                {status === 'success' && (
                    <span className="text-[0.55rem] font-black text-emerald-400 uppercase tracking-widest leading-none animate-bounce origin-bottom">DEPOSITED</span>
                )}
            </div>

            <div className="w-full mt-auto relative z-10">
                {timeLeft > 0 ? (
                    <div className="h-7 w-full bg-slate-900 border border-slate-700 rounded-lg flex items-center justify-center gap-1.5 overflow-hidden">
                        <svg className="w-2.5 h-2.5 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-tighter tabular-nums">
                            {formatTime(timeLeft)}
                        </span>
                    </div>
                ) : (
                    <HexButton 
                        variant={status === 'success' ? 'success' : (isFree ? 'success' : 'secondary')} 
                        size="sm" 
                        fullWidth
                        onClick={handlePurchase}
                        disabled={status !== 'idle'}
                        holdDuration={3000}
                        onHoldChange={setIsHolding}
                        onProgressChange={setHoldProgress}
                    >
                        {status === 'processing' ? "SYNCING" : (status === 'success' ? "SYNCED" : (isFree ? "FREE" : <div className="flex items-center justify-center gap-1"><GoldIcon /> {cost}</div>))}
                    </HexButton>
                )}
            </div>
        </div>
    );
};

