                {status === 'success' && (
                    <span className="text-[0.55rem] font-black text-emerald-400 uppercase tracking-widest leading-none animate-bounce origin-bottom">DEPOSITED</span>
                )}
            </div>

            <div className="w-full mt-1 relative z-10">
                <HexButton 
                    variant={status === 'success' ? 'success' : 'primary'} 
                    size="sm"
                    fullWidth 
