import React, { useState, useEffect } from 'react';
import { HexButton } from '../ui/HexButton';
import { useUser } from '../../contexts/UserContext';
import { audio } from '../../services/audio';

interface StoreCreditItemProps {
    amount: number;
    cost: number | 'FREE';
    offerId?: string; 
    availableAt?: string; 
}

export const StoreCreditItem: React.FC<StoreCreditItemProps> = ({ amount, cost, offerId, availableAt }) => {
    const { spendGold, addCredits, processPurchase } = useUser();
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');
    const isFree = cost === 'FREE';

    const [timeLeft, setTimeLeft] = useState<number>(0);

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handlePurchase = async () => {
        if (timeLeft > 0 || status !== 'idle') return;

        setStatus('processing');

        let success = false;
        if (isFree && offerId) {
            success = await processPurchase(offerId);
        } else if (isFree) {
            addCredits(amount);
            success = true;
        } else {
            const hasFunds = spendGold(cost as number);
            if (hasFunds) {
                addCredits(amount);
                success = true;
            } else {
                alert("Not enough Gold!");
                setStatus('idle');
                return;
            }
        }

        if (success) {
            // Simulated network "sync" delay for visual consistency
            setTimeout(() => {
                setStatus('success');
                audio.play('sfx_victory', 0.5);
                setTimeout(() => setStatus('idle'), 2500);
            }, 800);
        } else {
            setStatus('idle');
        }
    };

    const formatTime = (seconds: number) => {
        if (seconds < 60) return `${seconds}s`;
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}m ${s}s`;
    };

    const GoldIcon = () => (
        <div className="w-2 h-1.5 rounded-[1px] bg-amber-400 shadow-[0_0_0.25rem_rgba(251,191,36,1)] border border-white/40"></div>
    );

    return (
        <div className={`bg-gradient-to-b from-slate-900 to-black border-2 transition-all duration-300 rounded-xl p-2 flex flex-col items-center justify-between gap-1 h-full relative group shadow-[0_4px_15px_rgba(0,0,0,0.8)] overflow-hidden ${status === 'success' ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-600'}`}>
            {/* Purchase Success Flash */}
            {status === 'success' && (
                <div className="absolute inset-0 bg-white/40 animate-pulse z-40 pointer-events-none" />
            )}

            {/* Obnoxiously Bright Hold Progress Background (Only if not free) */}
            {holdProgress > 0 && status === 'idle' && !isFree && (
                <div 
                    className="absolute inset-y-0 left-0 bg-cyan-400 shadow-[0_0_2rem_rgba(34,211,238,1)] z-0 transition-all duration-75 ease-linear"
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {isFree && timeLeft === 0 && status === 'idle' && (
                <div className="absolute -top-1 -left-1 z-30">
                     <div className="bg-emerald-500 text-white text-[0.45rem] font-black px-1.5 py-0.5 rounded shadow-[0_0_10px_rgba(16,185,129,0.8)] uppercase tracking-wider border border-white/40">
                        READY
                     </div>
                </div>
            )}

            <div className="mt-1 font-black text-white text-sm leading-none text-center drop-shadow-[0_2px_2px_rgba(0,0,0,1)] italic relative z-10">
                {amount}
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-1 min-h-[3rem] relative z-10">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${status === 'success' ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_25px_rgba(16,185,129,1)]' : 'bg-blue-900 border-blue-400 shadow-[inset_0_0_10px_rgba(0,0,0,0.5)]'}`}>
                    {status === 'success' ? (
                        <svg className="w-6 h-6 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        <div className="w-7 h-7 rounded-sm bg-gradient-to-tr from-blue-400 to-blue-600 shadow-xl border border-white/30 transform rotate-45"></div>
                    )}
                </div>
            </div>

            {/* Feedback Area */}
            <div className="w-full h-3.5 relative flex items-center justify-center pointer-events-none mb-1 z-10 overflow-visible">
                {isHolding && status === 'idle' && !isFree && (
                    <div className="relative font-black text-[0.55rem] uppercase tracking-widest leading-none drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                        <span className="text-white/40 whitespace-nowrap">HOLD TO BUY</span>
                        <div 
                            className="absolute inset-0 text-white whitespace-nowrap overflow-hidden transition-all duration-75 ease-linear"
                            style={{ width: `${holdProgress}%` }}
                        >
                            HOLD TO BUY
                        </div>
                    </div>
                )}
                {status === 'processing' && (
                    <span className="text-[0.55rem] font-black text-cyan-300 uppercase tracking-[0.25em] leading-none animate-pulse drop-shadow-[0_0_5px_rgba(34,211,238,0.8)]">SYNCING...</span>
                )}
                {status === 'success' && (
                    <span className="text-[0.55rem] font-black text-emerald-400 uppercase tracking-[0.25em] leading-none animate-bounce pt-0.5 drop-shadow-[0_0_5px_rgba(52,211,153,0.8)]">DEPOSITED</span>
                )}
            </div>

            <div className="w-full mt-auto relative z-10">
                {timeLeft > 0 ? (
                    <div className="h-7 w-full bg-slate-900 border-2 border-slate-700 rounded-lg flex items-center justify-center gap-1.5 overflow-hidden">
                        <svg className="w-2.5 h-2.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <span className="text-[0.6rem] font-black text-slate-400 uppercase tracking-tighter tabular-nums">
                            {formatTime(timeLeft)}
                        </span>
                    </div>
                ) : (
                    <HexButton 
                        variant={status === 'success' ? 'success' : (isFree ? 'success' : 'secondary')} 
                        size="sm" 
                        fullWidth
                        onClick={handlePurchase}
                        disabled={status !== 'idle'}
                        holdDuration={isFree ? 0 : 3000}
                        onHoldChange={setIsHolding}
                        onProgressChange={setHoldProgress}
                    >
                        {status === 'processing' ? "SYNCING" : (status === 'success' ? "SYNCED" : (isFree ? "FREE" : <div className="flex items-center justify-center gap-1"><GoldIcon /> {cost}</div>))}
                    </HexButton>
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { HexButton } from '../ui/HexButton';
import { useUser } from '../../contexts/UserContext';
import { audio } from '../../services/audio';

interface StoreGoldItemProps {
    amount: number;
    price: string;
    badge: string | null;
    visualIndex: number; 
}

export const StoreGoldItem: React.FC<StoreGoldItemProps> = ({ amount, price, badge, visualIndex }) => {
    const { addGold } = useUser();
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');

    const handlePurchase = () => {
        if (status !== 'idle') return;

        setStatus('processing');
        // Simulated network delay
        setTimeout(() => {
            addGold(amount);
            setStatus('success');
            audio.play('sfx_victory', 0.5);

            // Lockout for visual confirmation
            setTimeout(() => {
                setStatus('idle');
                setHoldProgress(0);
            }, 2500);
        }, 900);
    };

    return (
        <div className={`bg-gradient-to-b from-slate-900 to-black border-2 transition-all duration-300 rounded-xl p-2 flex flex-col items-center justify-between h-full relative group overflow-hidden shadow-[0_4px_15px_rgba(0,0,0,0.8)] ${status === 'success' ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-600'}`}>
            {/* Purchase Success Flash */}
            {status === 'success' && (
                <div className="absolute inset-0 bg-white/40 animate-pulse z-40 pointer-events-none" />
            )}

            {/* Obnoxiously Bright Yellow Hold Progress Background */}
            {holdProgress > 0 && status === 'idle' && (
                <div 
                    className="absolute inset-y-0 left-0 bg-amber-400 shadow-[0_0_2rem_rgba(251,191,36,1)] z-0 transition-all duration-75 ease-linear"
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {badge && status === 'idle' && (
                <div className="absolute -top-1 -right-1 z-30 bg-red-600 border border-red-400 text-white text-[0.45rem] font-black px-1.5 py-0.5 rounded shadow-[0_0_10px_rgba(220,38,38,0.8)] uppercase tracking-tight skew-x-[-10deg]">
                    {badge}
                </div>
            )}

            <div className="mt-1 flex items-center justify-center gap-1 w-full relative z-10">
                <div className="w-2.5 h-2 bg-amber-400 rounded-[1px] shadow-[0_0_0.3125rem_rgba(251,191,36,1)] border border-white/30"></div>
                <div className="font-black text-amber-500 text-sm leading-none text-center drop-shadow-[0_2px_2px_rgba(0,0,0,1)] italic">
                    {amount}
                </div>
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-2 relative min-h-[3.5rem] z-10">
                <div className="absolute inset-0 bg-amber-500/15 blur-xl rounded-full scale-75"></div>

                <div className={`relative z-10 flex flex-wrap gap-0.5 justify-center items-center transition-all duration-500 ${status === 'success' ? 'scale-110' : ''}`}>
                    {status === 'success' ? (
                         <div className="w-10 h-10 rounded-full bg-emerald-500 border-2 border-emerald-300 flex items-center justify-center shadow-[0_0_20px_rgba(16,185,129,1)]">
                            <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                         </div>
                    ) : (
                        amount < 1450 ? (
                             <div className="w-9 h-5 bg-gradient-to-br from-amber-300 via-yellow-400 to-amber-600 border border-white/20 rounded-sm shadow-xl transform -rotate-6"></div>
                        ) : (
                             <div className="relative flex flex-col items-center">
                                 <div className="w-11 h-6 bg-gradient-to-br from-amber-300 via-yellow-400 to-amber-600 border border-white/30 rounded-sm shadow-xl transform rotate-3 -translate-y-1"></div>
                                 <div className="w-9 h-5 bg-gradient-to-br from-amber-400 via-yellow-500 to-amber-700 border border-white/20 rounded-sm shadow-lg transform -rotate-6 -mt-3 ml-2"></div>
                             </div>
                        )
                    )}
                </div>
            </div>

            {/* Feedback Area */}
            <div className="w-full h-3.5 relative flex items-center justify-center pointer-events-none mb-1 z-10 overflow-visible">
                {isHolding && status === 'idle' && (
                    <div className="relative font-black text-[0.55rem] uppercase tracking-widest leading-none drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                        <span className="text-white/40 whitespace-nowrap">HOLD TO BUY</span>
                        <div 
                            className="absolute inset-0 text-white whitespace-nowrap overflow-hidden transition-all duration-75 ease-linear"
                            style={{ width: `${holdProgress}%` }}
                        >
                            HOLD TO BUY
                        </div>
                    </div>
                )}
                {status === 'processing' && (
                    <span className="text-[0.55rem] font-black text-amber-300 uppercase tracking-[0.25em] leading-none animate-pulse drop-shadow-[0_0_5px_rgba(245,158,11,0.8)]">SYNCING...</span>
                )}
                {status === 'success' && (
                    <span className="text-[0.55rem] font-black text-emerald-400 uppercase tracking-[0.25em] leading-none animate-bounce pt-0.5 drop-shadow-[0_0_5px_rgba(52,211,153,0.8)]">DEPOSITED</span>
                )}
            </div>

            <div className="w-full mt-1 relative z-10">
                <HexButton 
                    variant={status === 'success' ? 'success' : 'primary'} 
                    size="sm"
                    fullWidth 
                    onClick={handlePurchase}
                    disabled={status !== 'idle'}
                    holdDuration={3000}
                    onHoldChange={setIsHolding}
                    onProgressChange={setHoldProgress}
                >
                    {status === 'processing' ? 'SYNCING' : (status === 'success' ? 'SUCCESS' : price)}
                </HexButton>
            </div>
        </div>
    );
};

