export const api = {
    async submitTurn(gameState: GameState, playerMoves: PendingMove[]): Promise<{ opponentMoves: PendingMove[] }> {
        const latency = 400 + Math.random() * 400;
        await new Promise(resolve => setTimeout(resolve, latency));
        const opponentMoves = generateAiMoves(gameState);
        return { opponentMoves };
    },

    /**
     * Authoritative store data fetching.
     * Returns metadata to tell the client when to refresh next.
     */
    async getStoreOffers(user: UserProfile): Promise<StoreData> {
        // Simulate moderate latency only for the first load
        await new Promise(resolve => setTimeout(resolve, 600)); 

        const filteredOffers = MOCK_STORE_OFFERS.filter(offer => {
            if (offer.isOneTime && user.purchasedOfferIds.includes(offer.id)) return false;

            if (offer.purchaseLimit) {
                const count = user.purchasedOfferIds.filter(id => id === offer.id).length;
                if (count >= offer.purchaseLimit) return false;
            }

            if (offer.expiryDate && new Date(offer.expiryDate) < new Date()) return false;

            return true;
        }).map(offer => {
            // Computed field: availableAt
            if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
                const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
                const availableAt = new Date(lastClaimed + (offer.cooldownSeconds * 1000));
                return { ...offer, availableAt: availableAt.toISOString() };
            }
            return offer;
        });

        return {
            offers: filteredOffers,
            lastUpdated: Date.now(),
            refreshHintSeconds: 60 // Server-directed: Refresh every 60s
        };
    },

    /**
     * TRANSACTIONAL PURCHASE
     */
    async purchaseOffer(user: UserProfile, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400));

        if (processedTransactions.has(transactionId)) {
            return { success: false, errorCode: 'ERR_DUPLICATE_TRANSACTION', transactionId };
        }

        const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
        if (!offer) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId };

        if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
            const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
            const now = Date.now();
            if (now < lastClaimed + (offer.cooldownSeconds * 1000)) {
                return { success: false, errorCode: 'ERR_COOLDOWN_ACTIVE', transactionId };
            }
        }

        if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) {
            return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        }
        if (offer.priceType === 'credits' && user.credits < (offer.priceAmount || 0)) {
            return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        }

        processedTransactions.add(transactionId);

        const updatedProfile: UserProfile = { ...user };

        if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
        if (offer.priceType === 'credits') updatedProfile.credits -= (offer.priceAmount || 0);

        offer.contents.forEach(item => {
            if (item.type === 'currency') {
                if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
            } else if (item.type === 'card') {
                if (!updatedProfile.collection.includes(item.definitionId)) {
                    updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
                }
            }
        });

        updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];
        updatedProfile.lastClaimedDates = { ...updatedProfile.lastClaimedDates, [offerId]: new Date().toISOString() };

        return { 
            success: true, 
            transactionId, 
            updatedProfile 
        };
    }
};

import React, { useState, useEffect } from 'react';
import { HexButton } from '../ui/HexButton';
import { useUser } from '../../contexts/UserContext';
import { audio } from '../../services/audio';

interface StoreCreditItemProps {
    amount: number;
    cost: number | 'FREE';
    offerId?: string; 
    availableAt?: string; 
}

export const StoreCreditItem: React.FC<StoreCreditItemProps> = ({ amount, cost, offerId, availableAt }) => {
    const { user, spendGold, addCredits, processPurchase, syncStore } = useUser();
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');
    const isFree = cost === 'FREE';

    const [timeLeft, setTimeLeft] = useState<number>(0);
    const hasEnoughGold = isFree || user.gold >= (cost as number);

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handlePurchase = async () => {
        if (timeLeft > 0 || status !== 'idle') return;

        if (!hasEnoughGold) {
            syncStore();
            return;
        }

        setStatus('processing');

        let success = false;
        if (isFree && offerId) {
            success = await processPurchase(offerId);
        } else if (isFree) {
            addCredits(amount);
            success = true;
        } else {
            const hasFunds = spendGold(cost as number);
            if (hasFunds) {
                addCredits(amount);
                success = true;
            } else {
                setStatus('idle');
                syncStore();
                return;
            }
        }

        if (success) {
            setTimeout(() => {
                setStatus('success');
                audio.play('sfx_victory', 0.5);
                setTimeout(() => setStatus('idle'), 2500);
            }, 800);
        } else {
            setStatus('idle');
        }
    };

    const formatTime = (seconds: number) => {
        if (seconds < 60) return `${seconds}s`;
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}m ${s}s`;
    };

    const GoldIcon = () => (
        <div className="w-2 h-1.5 rounded-[1px] bg-amber-400 shadow-[0_0_0.25rem_rgba(251,191,36,1)] border border-white/40"></div>
    );

    return (
        <div className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded-md p-2 flex flex-col items-center justify-between gap-1 h-[10rem] relative group shadow-[0_4px_15px_rgba(0,0,0,0.8)] overflow-hidden ${status === 'success' ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}>
            {status === 'success' && (
                <div className="absolute inset-0 bg-white/40 animate-pulse z-40 pointer-events-none" />
            )}

            {holdProgress > 0 && status === 'idle' && !isFree && hasEnoughGold && (
                <div 
                    className="absolute inset-y-0 left-0 bg-cyan-300 shadow-[0_0_2rem_rgba(34,211,238,1),0_0_4rem_rgba(34,211,238,0.5)] z-0 transition-all duration-75 ease-linear"
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            <div className="mt-1 font-black text-white text-sm leading-none text-center drop-shadow-[0_2px_2px_rgba(0,0,0,1)] italic relative z-10">
                {amount}
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-1 min-h-[2.5rem] relative z-10">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${status === 'success' ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_25px_rgba(16,185,129,1)]' : 'bg-blue-900 border-blue-400 shadow-[inset_0_0_10px_rgba(0,0,0,0.5)]'}`}>
                    {status === 'success' ? (
                        <svg className="w-6 h-6 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        <div className="w-7 h-7 rounded-sm bg-gradient-to-tr from-blue-400 to-blue-600 shadow-xl border border-white/30 transform rotate-45"></div>
                    )}
                </div>
            </div>

            <div className="w-full h-1 relative flex items-center justify-center pointer-events-none mb-0.5 z-10 overflow-visible">
                {isHolding && status === 'idle' && !isFree && hasEnoughGold && (
                    <div className="relative font-black text-[0.45rem] uppercase tracking-widest leading-none drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                        <span className="text-white/40 whitespace-nowrap">HOLD TO BUY</span>
                        <div 
                            className="absolute inset-0 text-white whitespace-nowrap overflow-hidden transition-all duration-75 ease-linear"
                            style={{ width: `${holdProgress}%` }}
                        >
                            HOLD TO BUY
                        </div>
                    </div>
                )}
                {status === 'processing' && (
                    <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.25em] leading-none animate-pulse drop-shadow-[0_0_5px_rgba(34,211,238,0.8)]">SYNCING...</span>
                )}
                {status === 'success' && (
                    <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.25em] leading-none animate-bounce origin-bottom drop-shadow-[0_0_5px_rgba(52,211,153,0.8)]">DEPOSITED</span>
                )}
            </div>

            <div className="w-full mt-auto relative z-10">
                {timeLeft > 0 ? (
                    <div className="h-7 w-full bg-slate-900 border-2 border-slate-700 rounded-md flex items-center justify-center gap-1.5 overflow-hidden">
                        <svg className="w-2.5 h-2.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <span className="text-[0.6rem] font-black text-slate-400 uppercase tracking-tighter tabular-nums">
                            {formatTime(timeLeft)}
                        </span>
                    </div>
                ) : (
                    <div className="h-7">
                        <HexButton 
                            variant={status === 'success' ? 'success' : (isFree ? 'success' : 'secondary')} 
                            size="sm" 
                            fullWidth
                            onClick={handlePurchase}
                            disabled={status !== 'idle'}
                            holdDuration={isFree || !hasEnoughGold ? 0 : 2000}
                            onHoldChange={setIsHolding}
                            onProgressChange={setHoldProgress}
                        >
                            {status === 'processing' ? "SYNCING" : (status === 'success' ? "SYNCED" : (isFree ? "FREE" : <div className="flex items-center justify-center gap-1"><GoldIcon /> {cost}</div>))}
                        </HexButton>
                    </div>
                )}
            </div>
        </div>
    );
};

