import React, { useState, useRef, useEffect } from 'react';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    holdDuration?: number; // Duration in ms to hold before triggering
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizes = {
        sm: "h-7 text-[0.85rem]",
        md: "h-9 text-[1.05rem]",
        lg: "h-12 text-[1.3rem]"
    };

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                if (onClick) {
                    // Create a robust synthetic event for onClick callbacks that might try to stop propagation
                    const syntheticEvent = { 
                        clientX: e.clientX,
                        clientY: e.clientY,
                        target: e.target,
                        currentTarget: e.currentTarget,
                        type: 'click',
                        stopPropagation: () => {}, // Mocked to prevent errors in callbacks
                        preventDefault: () => {}   // Mocked to prevent errors in callbacks
                    } as unknown as React.MouseEvent<HTMLButtonElement>;
                    onClick(syntheticEvent);
                }
                setIsHolding(false);
                onHoldChange?.(false);
                setProgress(0);
                onProgressChange?.(0);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthClass = fullWidth ? 'w-full' : '';

    return (
        <div className={`relative group ${widthClass} ${sizes[size]} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                <div className="absolute inset-0 flex items-center justify-center z-20 skew-x-[-10deg] px-0.5 pointer-events-none">
                    <span className={`font-black text-white italic tracking-tighter uppercase drop-shadow-md flex items-center gap-1 whitespace-nowrap transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {children}
                    </span>
                </div>
            </button>
        </div>
    );
};

import React from 'react';
import { useGameLogic } from './useGameLogic';
import { useDragAndDrop } from './useDragAndDrop';
import { useEventSystem } from './useEventSystem';
import { CardDefinition, CardInstance, LocationDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export const useGameController = (onExit?: () => void) => {
    const logic = useGameLogic();
    const { inspect, closeInspector } = useUser();

    // Mount Event System (Handles Audio & VFX)
    const eventSystem = useEventSystem(logic.events);

    // Initialize Drag and Drop
    const dnd = useDragAndDrop({
        gameState: logic.gameState,
        pendingMoves: logic.pendingMoves,
        isResolving: logic.isResolving,
        setPendingMoves: logic.setPendingMoves,
        setInspectingCard: (card: CardInstance | CardDefinition | null) => logic.setInspectingCard(card),
        setInspectingLocation: (loc: LocationDefinition | null) => logic.setInspectingLocation(loc),
        setSelectedCardIdx: logic.setSelectedCardIdx,
        setShowUndoMenu: logic.setShowUndoMenu,
        onDrop: (success) => {
            if (success) eventSystem.playSnap();
        }
    });

    // --- Wrapped Actions (Logic + Audio) ---

    const handleCardClick = (idx: number, isDragging: boolean) => {
        if (!isDragging) {
            eventSystem.playClick();
            logic.handleCardClick(idx, isDragging);

            // Sync with Global Inspector
            const card = logic.gameState.players.p1.hand[idx];
            if (card) inspect(card);
        }
    };

    const handleLocationClick = (laneIdx: number) => {
        if (logic.selectedCardIdx !== null) {
            eventSystem.playSnap();
        }
        logic.handleLocationClick(laneIdx);
    };

    const handleUndoAll = () => {
        eventSystem.playClick();
        logic.handleUndoAll();
    };

    const handleEndTurn = () => {
        eventSystem.playClick();
        logic.handleEndTurn();
    };

    const handleResign = () => {
        eventSystem.playClick();
        logic.handleResign();
    };

    const restartGame = () => {
        eventSystem.playClick();
        logic.restartGame();
    };

    const handleExit = () => {
        eventSystem.playClick();
        if (onExit) onExit();
    };

    const toggleResults = (val: boolean) => {
        eventSystem.playClick();
        logic.setIsResultsHidden(val);
    };

    const wrappedCloseInspector = () => {
        eventSystem.playClick();
        closeInspector();
        logic.setInspectingCard(null);
        logic.setInspectingLocation(null);
    };

    const wrappedInspectCard = (c: CardInstance | CardDefinition) => {
        eventSystem.playClick();
        inspect(c);
        logic.setInspectingCard(c);
    };

    const wrappedInspectLocation = (l: LocationDefinition) => {
        eventSystem.playClick();
        inspect(l);
        logic.setInspectingLocation(l);
    };

    const handleCardPointerDownHand = (e: React.PointerEvent, card: CardInstance, idx: number) => {
        dnd.handleCardPointerDown(e, card, { type: 'hand', index: idx });
    };

    const handleCardPointerDownLane = (e: React.PointerEvent, card: CardInstance, laneIdx: number) => {
        dnd.handleCardPointerDown(e, card, { type: 'lane', laneIdx });
    };

    return {
        // State
        gameState: logic.gameState,
        pendingMoves: logic.pendingMoves,
        isResolving: logic.isResolving,
        isWaiting: logic.isWaiting,
        currentEnergy: logic.currentEnergy,
        isResultsHidden: logic.isResultsHidden,
        showUndoMenu: logic.showUndoMenu,
        inspectingCard: logic.inspectingCard,
        inspectingLocation: logic.inspectingLocation,
        selectedCardIdx: logic.selectedCardIdx,
        dragState: dnd.dragState,
        activeVfx: eventSystem.activeVfx,

        setShowUndoMenu: logic.setShowUndoMenu,

        // Actions
        actions: {
            handleCardClick,
            handleUndoAll,
            handleEndTurn,
            handleResign,
            restartGame,
            handleExit,
            toggleResults,
            closeInspector: wrappedCloseInspector,
            inspectCard: wrappedInspectCard,
            inspectLocation: wrappedInspectLocation,
            handleLocationClick,
            handleCardPointerDownHand,
            handleCardPointerDownLane
        }
    };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { GameState, GameEvent } from '../types';
import { createInitialGameState, moveCardsToBoard, getNextReveal, revealCard, resolveEndOfTurn, startNextTurn, calculateWinner, stepExecutionQueue } from '../services/engine';
import { PendingMove } from '../services/planning';

export const useTurnManager = () => {
    const [gameState, setGameState] = useState<GameState>(createInitialGameState());
    const [events, setEvents] = useState<GameEvent[]>([]);
    const [isResolving, setIsResolving] = useState(false);
    const [isWaiting, setIsWaiting] = useState(false);

    // Use a ref to track the latest state without causing effect re-runs
    const gameStateRef = useRef(gameState);
    useEffect(() => { 
        gameStateRef.current = gameState; 
    }, [gameState]);

    const updateStateWithEvents = useCallback((newState: GameState) => {
        if (newState.eventQueue.length > 0) {
             const newEvents = [...newState.eventQueue];
             newState.eventQueue = [];
             setEvents(prev => [...prev, ...newEvents]);
        }
        setGameState(newState);
    }, []);

    const startResolution = useCallback((p1Moves: PendingMove[], p2Moves: PendingMove[]) => {
        setIsWaiting(false);
        const newState = moveCardsToBoard(gameState, p1Moves, p2Moves);
        newState.phase = 'resolving';
        updateStateWithEvents(newState);
        setIsResolving(true);
    }, [gameState, updateStateWithEvents]);

    // --- The Resolution Loop ---
    useEffect(() => {
        if (!isResolving) return;

        let active = true;

        const runLoop = async () => {
            if (!active) return;
            const currentState = gameStateRef.current;

            // 1. EXECUTION STACK PHASE
            if (currentState.executionQueue.length > 0) {
                const prevDestroyed = currentState.players.p1.stats.destroyedCount + currentState.players.p2.stats.destroyedCount;
                const nextState = stepExecutionQueue(currentState);
                updateStateWithEvents(nextState);

                const newDestroyed = nextState.players.p1.stats.destroyedCount + nextState.players.p2.stats.destroyedCount;
                const delay = (newDestroyed > prevDestroyed) ? 350 : 50; 

                setTimeout(runLoop, delay);
                return;
            }

            // 2. REVEAL PHASE
            const nextReveal = getNextReveal(currentState);
            if (nextReveal) {
                setTimeout(() => {
                    if (!active) return;
                    const s = revealCard(gameStateRef.current, nextReveal.laneIdx, nextReveal.slotIdx, nextReveal.owner);
                    updateStateWithEvents(s);
                    runLoop(); 
                }, 600);
                return;
            }

            // 3. END OF TURN TRANSITION
            const s = resolveEndOfTurn(currentState);
            if (s.executionQueue.length > 0) {
                updateStateWithEvents(s);
                setTimeout(runLoop, 50); 
                return;
            }

            // FINALIZATION
            let finalState = s;
            if (finalState.turn >= finalState.maxTurns) {
                finalState.phase = 'gameover';
                finalState.winner = calculateWinner(finalState);
                updateStateWithEvents(finalState);
                setIsResolving(false);
            } else {
                finalState = startNextTurn(finalState);
                updateStateWithEvents(finalState);

                // If StartOfTurn triggers exist, drain them before unlocking UI
                if (finalState.executionQueue.length > 0) {
                    setTimeout(runLoop, 50);
                    return;
                }

                setIsResolving(false);
            }
        };

        const t = setTimeout(runLoop, 100);
        return () => {
            active = false;
            clearTimeout(t);
        };

    }, [isResolving, updateStateWithEvents]);

    const restartGame = useCallback(() => {
        setGameState(createInitialGameState());
        setEvents([]);
        setIsResolving(false);
        setIsWaiting(false);
    }, []);

    const resign = useCallback(() => {
        if (gameState.winner) return;
        setGameState(prev => ({ ...prev, winner: 'p2', phase: 'gameover' }));
    }, [gameState.winner]);

    return {
        gameState,
        events,
        isResolving,
        isWaiting,
        setIsWaiting,
        startResolution,
        restartGame,
        resign
    };
};

import React from 'react';
