  isDragging?: boolean;
}

const CardComponent: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  variant = 'default', 
  hidden, 
  onPointerDown,
  isDragging
}) => {
  // Styles
  const sizeClasses = {
    xs: 'w-full aspect-[5/7] text-[0.5rem] rounded-md border', 
    sm: 'w-16 aspect-[5/7] text-[0.625rem] rounded-md border-2',
    md: 'w-20 aspect-[5/7] text-xs rounded-lg border-2',
    lg: 'w-64 aspect-[5/7] text-lg rounded-2xl border-4', 
  };
  const currentSizeClass = sizeClasses[size];

  if (hidden) {
      return (
        <div 
            role="presentation"
            className={`${currentSizeClass} bg-indigo-900 border-indigo-400 shadow-md flex items-center justify-center relative touch-none`}
        >
            <div className="w-1/3 h-1/3 rounded-full bg-indigo-500 animate-pulse"></div>
        </div>
      )
  }

  // Use Shared Utils
  const { 
      currentDisplayPower, currentDisplayCost, 
      powerColor, costColor, def 
  } = getCardStats(card);

  const borderColor = getCardBorderColor(def.tags);
  const opacityClass = isDragging ? 'opacity-50' : 'opacity-100';
  const cursorClass = onPointerDown || onClick ? 'cursor-grab active:cursor-grabbing' : '';
  const borderClass = size === 'xs' ? 'border' : (size === 'lg' ? 'border-4' : 'border-2');

  const ariaLabel = `${def.name}, Cost ${currentDisplayCost}, Power ${currentDisplayPower}. ${def.baseText}`;

  // VIEW SELECTION
  if (variant === 'board') {
    return (
        <CardBoardView 
            def={def}
            borderColor={borderColor}
            borderClass={borderClass}
            opacityClass={opacityClass}
            cursorClass={cursorClass}
            size={size}
            currentDisplayCost={currentDisplayCost}
            currentDisplayPower={currentDisplayPower}
            costColor={costColor}
            powerColor={powerColor}
            onPointerDown={onPointerDown}
            onClick={onClick}
        />
    );
  }

  if (size === 'lg') {
      return (
        <CardFullArtView 
            def={def}
            currentSizeClass={currentSizeClass}
            borderColor={borderColor}
            opacityClass={opacityClass}
            size={size}
            currentDisplayCost={currentDisplayCost}
            currentDisplayPower={currentDisplayPower}
            costColor={costColor}
            powerColor={powerColor}
        />
      );
  }

  return (
    <CardStandardView 
        def={def}
        currentSizeClass={currentSizeClass}
        borderColor={borderColor}
        opacityClass={opacityClass}
        cursorClass={cursorClass}
        size={size}
        currentDisplayCost={currentDisplayCost}
        currentDisplayPower={currentDisplayPower}
        costColor={costColor}
        powerColor={powerColor}
        onPointerDown={onPointerDown}
        onClick={onClick}
    />
  );
};

// Optimization: Memoize Card to prevent re-renders on unrelated state changes
export const Card = React.memo(CardComponent, (prev, next) => {
    if (prev.size !== next.size) return false;
    if (prev.variant !== next.variant) return false;
    if (prev.hidden !== next.hidden) return false;
    if (prev.isDragging !== next.isDragging) return false;
    if (prev.isSelected !== next.isSelected) return false;
    if (prev.isPlayable !== next.isPlayable) return false;

    const prevId = 'instanceId' in prev.card ? prev.card.instanceId : prev.card.id;
    const nextId = 'instanceId' in next.card ? next.card.instanceId : next.card.id;
    if (prevId !== nextId) return false;

    if ('instanceId' in prev.card && 'instanceId' in next.card) {
        if (prev.card.totalPower !== next.card.totalPower) return false;
        if (prev.card.totalCost !== next.card.totalCost) return false;
        if (prev.card.zone !== next.card.zone) return false;
        if (prev.card.faceUp !== next.card.faceUp) return false;
    }

    return true; 
});

import React, { useState, useRef, useEffect } from 'react';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizes = {
        sm: "h-7 text-[0.85rem]",
        md: "h-9 text-[1.05rem]",
        lg: "h-12 text-[1.3rem]"
    };

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                if (onClick) {
                    const syntheticEvent = { 
                        clientX: e.clientX,
                        clientY: e.clientY,
                        target: e.target,
                        currentTarget: e.currentTarget,
                        type: 'click',
                        bubbles: true,
                        cancelable: true,
                        defaultPrevented: false,
                        eventPhase: 3,
                        isTrusted: true,
                        nativeEvent: e.nativeEvent,
                        persist: () => {},
                        isDefaultPrevented: () => false,
                        isPropagationStopped: () => false,
                        stopPropagation: () => {}, 
                        preventDefault: () => {}   
                    } as unknown as React.MouseEvent<HTMLButtonElement>;
                    onClick(syntheticEvent);
                }
                setIsHolding(false);
                onHoldChange?.(false);
                setProgress(0);
                onProgressChange?.(0);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthClass = fullWidth ? 'w-full' : '';

    return (
        <div className={`relative group ${widthClass} ${sizes[size]} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                <div className="absolute inset-0 flex items-center justify-center z-20 skew-x-[-10deg] px-0.5 pointer-events-none">
                    <span className={`font-black text-white italic tracking-tighter uppercase drop-shadow-md flex items-center gap-1 whitespace-nowrap transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {children}
                    </span>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { AppShell } from './components/ui/AppShell';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { InspectorOverlay } from './components/InspectorOverlay';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  // --- Auth & Init State ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  // --- Navigation Logic (Extracted) ---
  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // --- App Initialization ---
  useEffect(() => {
    const initApp = async () => {
      await preloadAssets((progress) => setLoadingProgress(progress));
      setTimeout(() => setIsLoading(false), 500);
    };
    initApp();
  }, []);

  // --- Handlers ---
  const handleLogin = () => {
      audio.playUiClick();
      setIsLoggedIn(true);
  };

  const handleLogout = () => {
      audio.playUiClick();
      setIsLoggedIn(false);
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  // --- Render Flow ---

  // 1. Auth Gate
  if (!isLoggedIn) {
      return (
          <AppShell>
              <LoginScreen onLogin={handleLogin} />
          </AppShell>
      );
  }

  // 2. Main Application
  return (
    <UserProvider>
        <AppShell>
        {/* Global Inspector Overlay (Accessible from all screens) */}
        <InspectorOverlay />

        {/* Global Loading Overlay */}
        <div 
            className={`absolute inset-0 z-[100] transition-opacity duration-700 pointer-events-none ${isLoading ? 'opacity-100 pointer-events-auto' : 'opacity-0'}`}
        >
            {isLoading && <LoadingScreen progress={loadingProgress} />}
        </div>

        {/* The World Container (Infinite Canvas) */}
        <div 
            className="w-full h-full relative transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform"
            style={containerStyle}
        >
            {/* Screen Renderer */}
            {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
                // Culling Logic
                const shouldRender = key === activeScreen || (isTransitioning && key === prevScreen);

                if (!shouldRender) return null;

                const config = WORLDS[key];
                const ScreenComponent = config.component;

                return (
                    <div 
                        key={key}
                        className="absolute w-full h-full top-0 left-0 overflow-hidden"
                        style={{ 
                            transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)` 
                        }}
                    >
                        <ScreenComponent 
                            onNavigate={navigateTo} 
                            onExit={() => navigateTo('MENU')}
                            onBack={() => navigateTo('MENU')}
                            onStartGame={handleStartGame}
                            onLogout={handleLogout}
                        />
                    </div>
                );
            })}
        </div>

        {/* Global Navigation Bar (Hidden in Game) */}
        {activeScreen !== 'GAME' && !isLoading && (
            <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} />
        )}

        </AppShell>
    </UserProvider>
  );
}

import { useState } from 'react';
import { ScreenKey } from '../types';
import { WORLDS } from '../config/spatialMap';
import { audio } from '../services/audio';

export const useSpatialNavigation = () => {
    const [activeScreen, setActiveScreen] = useState<ScreenKey>('MENU');
    const [prevScreen, setPrevScreen] = useState<ScreenKey | null>(null);
    const [isTransitioning, setIsTransitioning] = useState(false);

    const navigateTo = (target: ScreenKey) => {
        if (target === activeScreen || isTransitioning) return;

        audio.playUiHover(); // Transition sound

        setPrevScreen(activeScreen);
        setActiveScreen(target);
        setIsTransitioning(true);

        // Culling Logic: Stop rendering the previous screen after animation completes
        // This matches the CSS duration (500ms) plus a small buffer
        setTimeout(() => {
            setIsTransitioning(false);
            setPrevScreen(null); 
        }, 550); 
    };

    const resetToMenu = () => {
        setActiveScreen('MENU');
        setPrevScreen(null);
        setIsTransitioning(false);
    };

    // Calculate Camera Position
    const activeConfig = WORLDS[activeScreen];
    const cameraX = activeConfig.x * -100; // Invert for "Camera" movement
    const cameraY = activeConfig.y * -100;

    const containerStyle = { 
        transform: `translate3d(${cameraX}%, ${cameraY}%, 0)` 
    };

    return {
        activeScreen,
        prevScreen,
        isTransitioning,
        containerStyle,
        navigateTo,
        resetToMenu,
        WORLDS // Exposed for rendering list
    };
};

