import React from 'react';
import { useGame } from '../contexts/GameContext';
import { Card } from './Card';

export const PlayerHand: React.FC = () => {
    const { gameState, pendingMoves, dragState, actions } = useGame();

    // 1. Filter to get visible cards only (exclude pending)
    const visibleCards = gameState.players.p1.hand
        .map((card, index) => ({ card, originalIndex: index }))
        .filter(({ card }) => !pendingMoves.some(m => m.cardInstanceId === card.instanceId));

    const count = visibleCards.length;

    // 2. Shrink logic
    // md (w-16), sm (w-14), xs (w-12)
    let cardSize: 'md' | 'sm' | 'xs' = 'sm';
    let gapClass = 'gap-1';
    let wrapperWidthClass = 'max-w-[3.2rem]'; // matches sm w-14 roughly at zoom

    if (count <= 3) {
        cardSize = 'md';
        gapClass = 'gap-1.5';
        wrapperWidthClass = 'max-w-[3.8rem]';
    } else if (count >= 6) {
        cardSize = 'xs';
        gapClass = 'gap-0.5';
        wrapperWidthClass = 'max-w-[2.8rem]';
    }

    return (
        <div 
            className="flex-none flex items-center justify-center px-2 py-0.5 min-h-[4.2rem] overflow-visible"
            data-drop-zone="hand"
        >
            <div className={`flex items-center justify-center w-full max-w-lg h-full transition-all duration-300 ${gapClass}`}>
                {visibleCards.map(({ card, originalIndex }) => {
                    const isDraggingThis = dragState?.active && dragState.card.instanceId === card.instanceId && dragState.origin.type === 'hand';

                    return (
                        <div 
                            key={card.instanceId} 
                            className={`
                                flex-1 min-w-0 ${wrapperWidthClass} transition-all duration-200 
                                ${isDraggingThis ? 'opacity-0' : ''}
                            `}
                        >
                            <div className="w-full aspect-[5/7]">
                                <Card 
                                    card={card} 
                                    size={cardSize} 
                                    onClick={() => actions.handleCardClick(originalIndex, !!dragState?.active)}
                                    onPointerDown={(e) => actions.handleCardPointerDownHand(e, card, originalIndex)}
                                />
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardInstance, CardDefinition, LocationDefinition, GameState } from '../types';
import { canInteractWithCard, canPlayCardToLane, PendingMove } from '../services/planning';

export interface DragState {
    active: boolean;
    card: CardInstance;
    origin: { type: 'hand', index: number } | { type: 'lane', laneIdx: number };
    startPos: { x: number, y: number };
    currentPos: { x: number, y: number };
    offset: { x: number, y: number };
    rect: DOMRect;
}

interface UseDragAndDropProps {
    gameState: GameState;
    pendingMoves: PendingMove[];
    isResolving: boolean;
    setPendingMoves: (moves: PendingMove[]) => void;
    setInspectingCard: (c: CardInstance | CardDefinition | null) => void;
    setInspectingLocation: (l: LocationDefinition | null) => void;
    setSelectedCardIdx: (i: number | null) => void;
    setShowUndoMenu: (b: boolean) => void;
    onDrop?: (success: boolean) => void;
}

export const useDragAndDrop = ({
    gameState,
    pendingMoves,
    isResolving,
    setPendingMoves,
    setInspectingCard,
    setInspectingLocation,
    setSelectedCardIdx,
    setShowUndoMenu,
    onDrop
}: UseDragAndDropProps) => {
    const [dragState, setDragState] = useState<DragState | null>(null);
    const hasMovedRef = useRef(false);

    // Use a ref for pending moves to avoid stale closure during the move lifecycle
    const pendingMovesRef = useRef(pendingMoves);
    useEffect(() => {
        pendingMovesRef.current = pendingMoves;
    }, [pendingMoves]);

    const handleCardPointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardInstance, 
        origin: { type: 'hand', index: number } | { type: 'lane', laneIdx: number }
    ) => {
        if (isResolving) return;

        // Note: We don't preventDefault here immediately so that native clicks/taps can still propagate
        // if we decide NOT to drag.

        // Check if interaction is allowed (Energy check happens here)
        if (!canInteractWithCard(gameState, pendingMovesRef.current, card, origin)) return;

        hasMovedRef.current = false;

        const target = e.currentTarget as HTMLElement;
        const rect = target.getBoundingClientRect();

        setDragState({
            active: false, // Start as inactive until threshold is met
            card,
            origin,
            startPos: { x: e.clientX, y: e.clientY },
            currentPos: { x: e.clientX, y: e.clientY },
            offset: { x: e.clientX - rect.left, y: e.clientY - rect.top },
            rect
        });
    }, [gameState, isResolving]);

    useEffect(() => {
        if (!dragState) return;

        const handleMove = (e: PointerEvent) => {
            const dist = Math.sqrt(Math.pow(e.clientX - dragState.startPos.x, 2) + Math.pow(e.clientY - dragState.startPos.y, 2));

            // 5px threshold to start "active" dragging
            if (!dragState.active && dist > 5) {
                hasMovedRef.current = true;
                setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);

                // Now we are sure it's a drag, lock UI
                setSelectedCardIdx(null);
                setShowUndoMenu(false);
                setInspectingCard(null);
                setInspectingLocation(null);
            } else if (dragState.active) {
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handleUp = (e: PointerEvent) => {
            if (!dragState) return;

            // If it never met the drag threshold, treat as a click
            if (!hasMovedRef.current) {
                // Inspection logic usually lives in components, but we can trigger it here or 
                // simply not swallow the event so onClick fires. 
                // Since PointerDown didn't preventDefault, onClick should fire naturally.
                setDragState(null);
                return;
            }

            const elements = document.elementsFromPoint(e.clientX, e.clientY);
            const laneZone = elements.find(el => el.getAttribute('data-drop-zone') === 'lane');
            const handZone = elements.find(el => el.getAttribute('data-drop-zone') === 'hand');

            let success = false;

            if (laneZone) {
                const laneIdx = parseInt(laneZone.getAttribute('data-lane-idx') || '0', 10);
                // Validate if dropping to this lane is possible (Capacity check)
                if (canPlayCardToLane(gameState, pendingMovesRef.current, dragState.card.instanceId, laneIdx, dragState.origin)) {
                    const existing = pendingMovesRef.current.filter(m => m.cardInstanceId !== dragState.card.instanceId);
                    setPendingMoves([...existing, { cardInstanceId: dragState.card.instanceId, laneIdx }]);
                    success = true;
                }
            } else if (handZone || (!laneZone && !handZone)) {
                // Return to hand if dropped in hand zone or empty space
                if (dragState.origin.type === 'lane') {
                    setPendingMoves(pendingMovesRef.current.filter(m => m.cardInstanceId !== dragState.card.instanceId));
                    success = true;
                }
            }

            onDrop?.(success);
            setDragState(null);
        };

        window.addEventListener('pointermove', handleMove);
        window.addEventListener('pointerup', handleUp);
        window.addEventListener('pointercancel', handleUp);

        return () => {
            window.removeEventListener('pointermove', handleMove);
            window.removeEventListener('pointerup', handleUp);
            window.removeEventListener('pointercancel', handleUp);
        };
    }, [dragState, gameState, setPendingMoves, onDrop, setSelectedCardIdx, setShowUndoMenu, setInspectingCard, setInspectingLocation]);

    return {
        dragState,
        handleCardPointerDown
    };
};

import React from 'react';
import { CardInstance, CardDefinition } from '../types';
import { CardBoardView } from './card/CardBoardView';
import { CardFullArtView } from './card/CardFullArtView';
import { CardStandardView } from './card/CardStandardView';
import { useCardStats } from '../hooks/useCardStats';

interface CardProps {
  card: CardInstance | CardDefinition;
  onClick?: () => void;
  isPlayable?: boolean;
  isSelected?: boolean;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  variant?: 'default' | 'board';
  hidden?: boolean;
  onPointerDown?: (e: React.PointerEvent) => void;
  isDragging?: boolean;
}

const CardComponent: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  variant = 'default', 
  hidden, 
  onPointerDown,
  isDragging
}) => {
  const sizeClasses = {
    xs: 'w-full aspect-[5/7] text-[0.45rem] rounded-sm border', 
    sm: 'w-13 aspect-[5/7] text-[0.55rem] rounded-md border-2',
    md: 'w-15 aspect-[5/7] text-[0.65rem] rounded-md border-2',
    lg: 'w-64 aspect-[5/7] text-lg rounded-2xl border-4', 
  };
  const currentSizeClass = sizeClasses[size];

  if (hidden) {
    return (
      <div 
          role="presentation"
          className={`${currentSizeClass} bg-indigo-900 border-indigo-400 shadow-md flex items-center justify-center relative touch-none pointer-events-auto`}
          onClick={onClick}
          onPointerDown={onPointerDown}
      >
          <div className="w-1/3 h-1/3 rounded-full bg-indigo-500 animate-pulse"></div>
      </div>
    );
  }

  const { 
    currentDisplayPower, currentDisplayCost, 
    powerColor, costColor, def, borderColor 
  } = useCardStats(card);

  const opacityClass = isDragging ? 'opacity-0 pointer-events-none' : 'opacity-100';
  const cursorClass = onPointerDown || onClick ? 'cursor-grab active:cursor-grabbing' : '';
  const borderClass = size === 'xs' ? 'border' : (size === 'lg' ? 'border-4' : 'border-2');

  const sharedProps = {
    def, borderColor, borderClass, opacityClass, cursorClass, size,
    currentDisplayCost, currentDisplayPower, costColor, powerColor,
    onPointerDown, onClick
  };

  if (variant === 'board') {
    return <CardBoardView {...sharedProps} />;
  }

  if (size === 'lg') {
    return <CardFullArtView {...sharedProps} currentSizeClass={currentSizeClass} />;
  }

  return <CardStandardView {...sharedProps} currentSizeClass={currentSizeClass} />;
};

export const Card = React.memo(CardComponent, (prev, next) => {
    if (prev.size !== next.size || prev.variant !== next.variant || prev.hidden !== next.hidden || prev.isDragging !== next.isDragging || prev.isSelected !== next.isSelected || prev.isPlayable !== next.isPlayable) return false;

    const prevId = 'instanceId' in prev.card ? prev.card.instanceId : prev.card.id;
    const nextId = 'instanceId' in next.card ? next.card.instanceId : next.card.id;
    if (prevId !== nextId) return false;

    if ('instanceId' in prev.card && 'instanceId' in next.card) {
        return (
            prev.card.totalPower === next.card.totalPower &&
            prev.card.totalCost === next.card.totalCost &&
            prev.card.zone === next.card.zone &&
            prev.card.faceUp === next.card.faceUp
        );
    }

    return true; 
});

