    const isInteractionDisabled = isResolving || isWaiting || gameState.phase !== 'planning';

    return (
        <div className="h-9 px-2 pb-0.5 grid grid-cols-3 items-center relative bg-slate-950/50 border-t border-slate-800">
            {gameState.winner ? (
                /* GAME OVER CONTROLS */
                <>
                    <div className="justify-self-start">
                        <HexButton variant="secondary" size="sm" onClick={() => actions.toggleResults(!isResultsHidden)}>
                            {isResultsHidden ? 'SHOW' : 'HIDE'}
                        </HexButton>
                    </div>
                    <div className="justify-self-center">
                        <HexButton variant="secondary" size="sm" onClick={actions.handleExit}>
                            MENU
                        </HexButton>
                    </div>
                    <div className="justify-self-end">
                        <HexButton variant="success" size="sm" onClick={actions.restartGame}>
                            RETRY
                        </HexButton>
                    </div>
                </>
            ) : (
                /* GAMEPLAY CONTROLS */
                <>
                    {/* RESIGN */}
                    <div className="justify-self-start min-w-[4rem]">
                        <HexButton variant="danger" size="sm" onClick={actions.handleResign} disabled={gameState.winner !== null}>
                            RESIGN
                        </HexButton>
                    </div>

                    {/* ENERGY & UNDO - Perfectly Centered */}
                    <div className="justify-self-center">
                        <EnergyOrb 
                            energy={currentEnergy}
                            showMenu={showUndoMenu}
                            disabled={isInteractionDisabled}
                            onClick={() => setShowUndoMenu(!showUndoMenu)}
                            onCloseMenu={() => setShowUndoMenu(false)}
                            onUndoAll={actions.handleUndoAll}
                        />
                    </div>

                    {/* END TURN */}
                    <div className="justify-self-end w-full max-w-[6.5rem]">
                        <HexButton 
                            variant="primary" 
                            size="md"
                            fullWidth
                            onClick={actions.handleEndTurn} 
                            disabled={gameState.winner !== null || isResolving || isWaiting}
                        >
                            <span className="text-[0.65rem]">
                                {isResolving ? 'WAIT...' : (isWaiting ? 'OPP...' : 'END TURN')}
                            </span>
                        </HexButton>
                    </div>
                </>
            )}
        </div>
    );
};

